--
-- Name: activar_lista_precios(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activar_lista_precios(p_lista_id uuid, p_desactivar_anteriores boolean DEFAULT true) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_proveedor_id UUID;
BEGIN
    -- Obtener proveedor de la lista
    SELECT proveedor_id INTO v_proveedor_id
    FROM proveedor_listas_precios
    WHERE id = p_lista_id;

    IF v_proveedor_id IS NULL THEN
        RETURN false;
    END IF;

    -- Desactivar listas anteriores del mismo proveedor si se solicita
    IF p_desactivar_anteriores THEN
        UPDATE proveedor_listas_precios
        SET estado = 'vencida', updated_at = NOW()
        WHERE proveedor_id = v_proveedor_id
          AND id != p_lista_id
          AND estado = 'activa';
    END IF;

    -- Activar la nueva lista
    UPDATE proveedor_listas_precios
    SET estado = 'activa', updated_at = NOW()
    WHERE id = p_lista_id;

    RETURN true;
END;
$$;


--
-- Name: actualizar_cliente_insumo_compra(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.actualizar_cliente_insumo_compra() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Actualizar cuando se crea un remito o pedido con items
  -- Se puede llamar desde triggers de remitos_items o pedidos_items
  UPDATE cliente_insumos_preferidos
  SET
    ultima_compra = CURRENT_DATE,
    total_compras = total_compras + 1,
    updated_at = NOW()
  WHERE cliente_id = NEW.cliente_id
    AND producto_id = NEW.producto_id
    AND activo = true;

  RETURN NEW;
END;
$$;


--
-- Name: actualizar_costo_materiales_instalacion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.actualizar_costo_materiales_instalacion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_costo_total numeric;
BEGIN
  -- Calcular suma de subtotales de items
  SELECT COALESCE(SUM(subtotal), 0)
  INTO v_costo_total
  FROM public.instalaciones_items
  WHERE instalacion_id = COALESCE(NEW.instalacion_id, OLD.instalacion_id);

  -- Actualizar costo_materiales en instalacion
  UPDATE public.instalaciones
  SET costo_materiales = v_costo_total
  WHERE id = COALESCE(NEW.instalacion_id, OLD.instalacion_id);

  RETURN COALESCE(NEW, OLD);
END;
$$;


