  RETURN NEW;
END;
$$;


--
-- Name: actualizar_precio_producto_desde_proveedor(uuid, boolean, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.actualizar_precio_producto_desde_proveedor(p_producto_id uuid, p_actualizar_venta boolean DEFAULT true, p_margen_default numeric DEFAULT 30) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_mejor_precio RECORD;
    v_precio_anterior NUMERIC;
BEGIN
    -- Obtener precio actual
    SELECT precio_costo INTO v_precio_anterior FROM productos WHERE id = p_producto_id;

    -- Obtener mejor precio de proveedor
    SELECT * INTO v_mejor_precio
    FROM obtener_precio_compra(p_producto_id)
    LIMIT 1;

    IF v_mejor_precio IS NULL THEN
        RETURN false;
    END IF;

    -- Actualizar producto
    UPDATE productos SET
        precio_costo = v_mejor_precio.precio_unitario,
        precio_venta = CASE
            WHEN p_actualizar_venta THEN v_mejor_precio.precio_unitario * (1 + p_margen_default / 100)
            ELSE precio_venta
        END,
        proveedor_habitual_id = v_mejor_precio.proveedor_id,
        ultima_compra_precio = v_mejor_precio.precio_unitario,
        ultima_compra_fecha = CURRENT_DATE
    WHERE id = p_producto_id;

    RETURN true;
END;
$$;


--
-- Name: actualizar_proxima_fecha_mantenimiento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.actualizar_proxima_fecha_mantenimiento() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_plan planes_mantenimiento;
    v_equipo_plan equipos_planes_mantenimiento;
    v_proxima_fecha DATE;
BEGIN
    -- Solo si el mantenimiento se completó
    IF NEW.estado = 'completado' AND (OLD.estado IS NULL OR OLD.estado != 'completado') THEN

        -- Obtener el equipo_plan
        SELECT * INTO v_equipo_plan
        FROM equipos_planes_mantenimiento
        WHERE id = NEW.equipo_plan_id;

        IF v_equipo_plan.id IS NOT NULL THEN
            -- Obtener el plan
            SELECT * INTO v_plan
            FROM planes_mantenimiento
            WHERE id = v_equipo_plan.plan_id;

            -- Calcular próxima fecha
            v_proxima_fecha := calcular_proxima_fecha_mantenimiento(
                COALESCE(NEW.fecha_fin::DATE, CURRENT_DATE),
                v_plan.frecuencia_tipo,
                COALESCE(v_equipo_plan.frecuencia_override_valor, v_plan.frecuencia_valor)
            );

            -- Actualizar equipo_plan
            UPDATE equipos_planes_mantenimiento
            SET
                ultima_fecha_mantenimiento = COALESCE(NEW.fecha_fin::DATE, CURRENT_DATE),
                proxima_fecha_mantenimiento = v_proxima_fecha,
                contador_ultimo_mantenimiento = NEW.contador_equipo,
                updated_at = NOW()
            WHERE id = NEW.equipo_plan_id;

        END IF;
    END IF;

    RETURN NEW;
END;
$$;


