--
-- Name: actualizar_saldos_contables(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.actualizar_saldos_contables(periodo_uuid uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Recalcular saldos para el período
  INSERT INTO saldos_contables (cuenta_id, periodo_id, movimientos_debe, movimientos_haber)
  SELECT
    ai.cuenta_id,
    periodo_uuid,
    COALESCE(SUM(ai.debe), 0),
    COALESCE(SUM(ai.haber), 0)
  FROM asientos_items ai
  JOIN asientos_contables ac ON ai.asiento_id = ac.id
  WHERE ac.periodo_id = periodo_uuid
    AND ac.estado = 'confirmado'
  GROUP BY ai.cuenta_id
  ON CONFLICT (cuenta_id, periodo_id, centro_costo_id)
  WHERE centro_costo_id IS NULL
  DO UPDATE SET
    movimientos_debe = EXCLUDED.movimientos_debe,
    movimientos_haber = EXCLUDED.movimientos_haber,
    saldo_final_debe = saldos_contables.saldo_inicial_debe + EXCLUDED.movimientos_debe,
    saldo_final_haber = saldos_contables.saldo_inicial_haber + EXCLUDED.movimientos_haber,
    updated_at = now();
END;
$$;


--
-- Name: actualizar_stock_deposito(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.actualizar_stock_deposito() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  nuevo_disponible INTEGER;
BEGIN
  -- Calcular el stock disponible total en todos los bins de este depósito
  SELECT COALESCE(SUM(sb.cantidad), 0)
  INTO nuevo_disponible
  FROM stock_bins sb
  JOIN deposito_bins db ON sb.bin_id = db.id
  WHERE sb.producto_id = NEW.producto_id
    AND db.deposito_id = (SELECT deposito_id FROM deposito_bins WHERE id = NEW.bin_id);

  -- Actualizar o insertar en stock_depositos
  INSERT INTO stock_depositos (producto_id, deposito_id, cantidad_disponible)
  VALUES (
    NEW.producto_id,
    (SELECT deposito_id FROM deposito_bins WHERE id = NEW.bin_id),
    nuevo_disponible
  )
  ON CONFLICT (producto_id, deposito_id)
  DO UPDATE SET
    cantidad_disponible = nuevo_disponible,
    updated_at = now();

  RETURN NEW;
END;
$$;


