CREATE FUNCTION public.actualizar_total_suscriptores_lista() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE email_listas
    SET total_contactos = total_contactos + 1
    WHERE id = NEW.lista_id;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE email_listas
    SET total_contactos = total_contactos - 1
    WHERE id = OLD.lista_id;
  END IF;
  RETURN NULL;
END;
$$;


