--
-- Name: calcular_clasificacion_abc(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calcular_clasificacion_abc() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  total_productos INTEGER;
  limite_a DECIMAL;
  limite_b DECIMAL;
BEGIN
  -- Calcular métricas por producto (últimos 12 meses)
  -- Esta es una versión simplificada - ajustar según tus necesidades
  INSERT INTO productos_clasificacion_abc (producto_id, valor_ventas_anual, clasificacion, score, ultima_actualizacion)
  SELECT
    p.id,
    COALESCE(SUM(fi.precio_unitario * fi.cantidad), 0) as valor_ventas,
    CASE
      WHEN ROW_NUMBER() OVER (ORDER BY COALESCE(SUM(fi.precio_unitario * fi.cantidad), 0) DESC) <= (COUNT(*) OVER () * 0.2) THEN 'A'
      WHEN ROW_NUMBER() OVER (ORDER BY COALESCE(SUM(fi.precio_unitario * fi.cantidad), 0) DESC) <= (COUNT(*) OVER () * 0.5) THEN 'B'
      ELSE 'C'
    END as clasificacion,
    COALESCE(SUM(fi.precio_unitario * fi.cantidad), 0) as score,
    now()
  FROM productos p
  LEFT JOIN facturas_items fi ON p.id = fi.producto_id
  LEFT JOIN facturas f ON fi.factura_id = f.id
  WHERE f.fecha >= CURRENT_DATE - INTERVAL '12 months' OR f.id IS NULL
  GROUP BY p.id
  ON CONFLICT (producto_id) DO UPDATE SET
    valor_ventas_anual = EXCLUDED.valor_ventas_anual,
    clasificacion = EXCLUDED.clasificacion,
    score = EXCLUDED.score,
    ultima_actualizacion = EXCLUDED.ultima_actualizacion;
END;
$$;


