--
-- Name: calcular_estadisticas_campana(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calcular_estadisticas_campana(p_campana_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE email_campanas
  SET
    total_enviados = (SELECT COUNT(*) FROM email_envios WHERE campana_id = p_campana_id AND estado != 'pendiente'),
    total_entregados = (SELECT COUNT(*) FROM email_envios WHERE campana_id = p_campana_id AND estado IN ('entregado', 'abierto', 'clicked')),
    total_abiertos = (SELECT COUNT(DISTINCT id) FROM email_envios WHERE campana_id = p_campana_id AND fecha_apertura IS NOT NULL),
    total_clicks = (SELECT COUNT(DISTINCT id) FROM email_envios WHERE campana_id = p_campana_id AND fecha_click IS NOT NULL),
    total_bounces = (SELECT COUNT(*) FROM email_envios WHERE campana_id = p_campana_id AND estado = 'bounce'),
    total_unsubscribes = (SELECT COUNT(*) FROM email_envios WHERE campana_id = p_campana_id AND estado = 'unsubscribed')
  WHERE id = p_campana_id;
END;
$$;


