-- Name: calcular_precio_venta(numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calcular_precio_venta(p_precio_costo numeric, p_margen_porcentaje numeric) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
  RETURN ROUND(p_precio_costo * (1 + p_margen_porcentaje / 100), 2);
END;
$$;


