--
-- Name: calcular_proxima_fecha_mantenimiento(date, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calcular_proxima_fecha_mantenimiento(p_ultima_fecha date, p_frecuencia_tipo character varying, p_frecuencia_valor integer) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    RETURN CASE p_frecuencia_tipo
        WHEN 'dias' THEN p_ultima_fecha + (p_frecuencia_valor || ' days')::INTERVAL
        WHEN 'meses' THEN p_ultima_fecha + (p_frecuencia_valor || ' months')::INTERVAL
        WHEN 'años' THEN p_ultima_fecha + (p_frecuencia_valor || ' years')::INTERVAL
        ELSE p_ultima_fecha + (p_frecuencia_valor || ' days')::INTERVAL
    END;
END;
$$;


--
-- Name: FUNCTION calcular_proxima_fecha_mantenimiento(p_ultima_fecha date, p_frecuencia_tipo character varying, p_frecuencia_valor integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calcular_proxima_fecha_mantenimiento(p_ultima_fecha date, p_frecuencia_tipo character varying, p_frecuencia_valor integer) IS 'Calcula la próxima fecha de mantenimiento según frecuencia';


--
-- Name: calcular_proximo_mantenimiento(timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calcular_proximo_mantenimiento(p_ultimo_mantenimiento timestamp with time zone, p_frecuencia_dias integer) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
  IF p_ultimo_mantenimiento IS NULL THEN
    RETURN CURRENT_TIMESTAMP + (p_frecuencia_dias || ' days')::INTERVAL;
  ELSE
    RETURN p_ultimo_mantenimiento + (p_frecuencia_dias || ' days')::INTERVAL;
  END IF;
END;
$$;


--
-- Name: calcular_stock_disponible(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calcular_stock_disponible(p_producto_id uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_stock_actual INTEGER;
    v_stock_reservado INTEGER;
BEGIN
    -- Obtener stock actual del producto
    SELECT COALESCE(stock_actual, 0) INTO v_stock_actual
    FROM public.productos
    WHERE id = p_producto_id;

    -- Calcular stock reservado activo
    SELECT COALESCE(SUM(cantidad), 0) INTO v_stock_reservado
    FROM public.stock_reservado
    WHERE producto_id = p_producto_id
    AND estado IN ('reservado', 'confirmado');

    RETURN GREATEST(v_stock_actual - v_stock_reservado, 0);
END;
$$;


--
-- Name: calcular_vpd(numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calcular_vpd(temp_c numeric, humedad_rh numeric) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  svp NUMERIC;
  avp NUMERIC;
BEGIN
  svp := 0.6108 * exp((17.27 * temp_c) / (temp_c + 237.3));
  avp := svp * (humedad_rh / 100);
  RETURN round((svp - avp)::NUMERIC, 2);
END;
$$;


--
-- Name: cerrar_periodo(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cerrar_periodo(periodo_uuid uuid, usuario_uuid uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  asientos_no_balanceados INTEGER;
  tareas_pendientes INTEGER;
BEGIN
  -- Verificar que no haya asientos desbalanceados
  SELECT COUNT(*)
  INTO asientos_no_balanceados
  FROM asientos_contables
  WHERE periodo_id = periodo_uuid
    AND estado = 'confirmado'
    AND total_debe != total_haber;

  IF asientos_no_balanceados > 0 THEN
    RAISE EXCEPTION 'Existen % asientos desbalanceados', asientos_no_balanceados;
  END IF;

  -- Verificar que todas las tareas obligatorias estén completadas
  SELECT COUNT(*)
  INTO tareas_pendientes
  FROM checklist_cierre cc
  JOIN checklist_cierre_template cct ON cc.template_id = cct.id
  WHERE cc.periodo_id = periodo_uuid
    AND cct.obligatorio = true
    AND cc.completado = false;

  IF tareas_pendientes > 0 THEN
    RAISE EXCEPTION 'Existen % tareas obligatorias pendientes', tareas_pendientes;
  END IF;

  -- Cerrar el período
  UPDATE periodos_contables
  SET
    estado = 'cerrado',
    fecha_cierre = now(),
    cerrado_por = usuario_uuid
  WHERE id = periodo_uuid;

  RETURN true;
END;
$$;


--
-- Name: convert_pg_array_to_json(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.convert_pg_array_to_json(input_text text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  result jsonb := '[]'::jsonb;
  arr text[];
  item text;
BEGIN
  IF input_text IS NULL OR input_text IN ('[]', 'null', '', '{}', 'NULL') THEN
    RETURN '[]'::jsonb;
  END IF;
  
  -- Si ya es JSON válido, retornarlo
  BEGIN
    result := input_text::jsonb;
    RETURN result;
  EXCEPTION WHEN OTHERS THEN
    -- Continuar con la conversión
  END;
  
  -- Intentar parsear como array de postgres
  BEGIN
    -- Extraer los elementos del array de postgres {"{...}","{...}"}
    arr := string_to_array(
      regexp_replace(
        regexp_replace(input_text, '^{', ''),
        '}$', ''
      ),
      '","'
    );
    
    result := '[]'::jsonb;
    FOREACH item IN ARRAY arr LOOP
      -- Limpiar las comillas extra
      item := regexp_replace(item, '^"', '');
      item := regexp_replace(item, '"$', '');
      -- Desescapar las comillas internas
      item := replace(item, '\"', '"');
      BEGIN
        result := result || item::jsonb;
      EXCEPTION WHEN OTHERS THEN
        -- Si falla, ignorar este item
        RAISE NOTICE 'Failed to parse: %', item;
      END;
    END LOOP;
    
    RETURN result;
  EXCEPTION WHEN OTHERS THEN
    RETURN '[]'::jsonb;
  END;
END;
$_$;


--
-- Name: crear_alerta_mantenimiento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crear_alerta_mantenimiento() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Create alert 7 days before maintenance is due
  IF NEW.requiere_mantenimiento AND NEW.proximo_mantenimiento IS NOT NULL THEN
    INSERT INTO equipos_alertas (
      equipo_unidad_id,
      tipo,
      prioridad,
      fecha_alerta,
      fecha_limite,
      dias_anticipacion,
      titulo,
      mensaje
    ) VALUES (
      NEW.id,
      'mantenimiento_proximo',
      'media',
      NEW.proximo_mantenimiento - INTERVAL '7 days',
      NEW.proximo_mantenimiento,
      7,
      'Mantenimiento próximo - ' || NEW.codigo,
      'El equipo ' || NEW.codigo || ' requiere mantenimiento programado'
    )
    ON CONFLICT DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: crear_alerta_vencimiento_contrato(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crear_alerta_vencimiento_contrato() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.estado = 'activo' AND NEW.fecha_fin IS NOT NULL THEN
    -- Alert 30 days before
    INSERT INTO equipos_alertas (
      contrato_id,
      equipo_unidad_id,
      cliente_id,
      tipo,
      prioridad,
      fecha_alerta,
      fecha_limite,
      dias_anticipacion,
      titulo,
      mensaje
    ) VALUES (
      NEW.id,
      NEW.equipo_unidad_id,
      NEW.cliente_id,
      'vencimiento_contrato',
      'alta',
      NEW.fecha_fin - INTERVAL '30 days',
      NEW.fecha_fin,
      30,
      'Contrato próximo a vencer',
      'El contrato de ' || NEW.tipo || ' vence el ' || NEW.fecha_fin::TEXT
    )
    ON CONFLICT DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: crear_notificacion_automatica(text, text, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crear_notificacion_automatica(p_tipo text, p_titulo text, p_mensaje text, p_entidad_tipo text, p_entidad_id uuid, p_prioridad text DEFAULT 'normal'::text) RETURNS uuid
