--
-- Name: FUNCTION crear_notificacion_automatica(p_tipo text, p_titulo text, p_mensaje text, p_entidad_tipo text, p_entidad_id uuid, p_prioridad text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.crear_notificacion_automatica(p_tipo text, p_titulo text, p_mensaje text, p_entidad_tipo text, p_entidad_id uuid, p_prioridad text) IS 'Crea una notificación automática del sistema';


--
-- Name: detectar_diferencias_cantidades(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detectar_diferencias_cantidades() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Si hay diferencia entre cantidad enviada y recibida
  IF NEW.cantidad_recibida IS NOT NULL
     AND NEW.cantidad_enviada != NEW.cantidad_recibida THEN

    -- Crear notificación
    PERFORM crear_notificacion_automatica(
      'diferencia_cantidad',
      'Diferencia en cantidades detectada',
      format('Item "%s": Enviado %s, Recibido %s',
             NEW.descripcion,
             NEW.cantidad_enviada,
             NEW.cantidad_recibida),
      'envio',
      NEW.envio_id,
      'alta'
    );

    -- Crear comentario automático
    INSERT INTO public.comentarios (
      entidad_tipo,
      entidad_id,
      usuario_nombre,
      comentario,
      tipo,
      es_importante,
      requiere_accion
    ) VALUES (
      'envio',
      NEW.envio_id,
      'Sistema',
      format('⚠️ Diferencia detectada en "%s": Se enviaron %s unidades pero se recibieron %s. Motivo: %s',
             NEW.descripcion,
             NEW.cantidad_enviada,
             NEW.cantidad_recibida,
             COALESCE(NEW.motivo_diferencia, 'No especificado')),
      'alerta',
      true,
      true
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: email_is_burned(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_is_burned(p_org_id uuid, p_email text) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_hard_count INT;
  v_soft_count INT;
BEGIN
  -- Hard bounce no resuelto = quemado
  SELECT COUNT(*) INTO v_hard_count
  FROM email_bounces
  WHERE org_id = p_org_id
    AND LOWER(email) = LOWER(p_email)
    AND bounce_type = 'hard'
    AND resuelto = false;

  IF v_hard_count > 0 THEN RETURN true; END IF;

  -- 3 soft bounces en los últimos 30 días = quemado
  SELECT COUNT(*) INTO v_soft_count
  FROM email_bounces
  WHERE org_id = p_org_id
    AND LOWER(email) = LOWER(p_email)
    AND bounce_type = 'soft'
    AND resuelto = false
    AND created_at >= NOW() - INTERVAL '30 days';

  RETURN v_soft_count >= 3;
END;
$$;


--
-- Name: FUNCTION email_is_burned(p_org_id uuid, p_email text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.email_is_burned(p_org_id uuid, p_email text) IS 'Devuelve true si el email tiene hard bounce o 3+ soft bounces en 30 días (per-org).';


--
-- Name: fn_cantidad_sugerida_cliente(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_cantidad_sugerida_cliente(p_cliente_id uuid, p_producto_id uuid, p_equipo_unidad_id uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cantidad NUMERIC;
BEGIN
  -- Buscar cantidad habitual específica del equipo primero
  SELECT cantidad_habitual INTO v_cantidad
  FROM cliente_insumos_preferidos
  WHERE cliente_id = p_cliente_id
    AND producto_id = p_producto_id
    AND equipo_unidad_id = p_equipo_unidad_id
    AND activo = true;

  -- Si no hay específica, buscar genérica del cliente
  IF v_cantidad IS NULL THEN
    SELECT cantidad_habitual INTO v_cantidad
    FROM cliente_insumos_preferidos
    WHERE cliente_id = p_cliente_id
      AND producto_id = p_producto_id
      AND equipo_unidad_id IS NULL
      AND activo = true;
  END IF;

  RETURN COALESCE(v_cantidad, 1);
END;
$$;


--
-- Name: fn_insumos_para_equipo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_insumos_para_equipo(p_equipo_id uuid) RETURNS TABLE(producto_id uuid, codigo text, nombre text, nombre_comercial text, categoria text, precio_venta numeric, stock_actual numeric, es_recomendado boolean, notas text)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    p.id,
    p.codigo,
    p.nombre,
    p.nombre_comercial,
    p.categoria,
    p.precio_venta,
    p.stock_actual,
    ei.es_recomendado,
    ei.notas
  FROM productos p
  JOIN equipos_insumos ei ON p.id = ei.producto_id
  WHERE ei.equipo_id = p_equipo_id
    AND ei.es_compatible = true
  ORDER BY ei.es_recomendado DESC, p.nombre_comercial NULLS LAST, p.nombre;
END;
$$;


