--
-- Name: fn_pedido_estado_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_pedido_estado_changed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.estado IS DISTINCT FROM NEW.estado THEN
    INSERT INTO pedidos_notas (pedido_id, tipo, contenido, estado_anterior, estado_nuevo)
    VALUES (
      NEW.id,
      'cambio_estado',
      'Estado cambiado de ' || COALESCE(OLD.estado, 'nuevo') || ' a ' || NEW.estado,
      OLD.estado,
      NEW.estado
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: generar_alertas_mantenimiento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generar_alertas_mantenimiento() RETURNS TABLE(equipos_alertados integer, alertas_creadas integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_equipo_plan RECORD;
    v_equipo RECORD;
    v_plan RECORD;
    v_dias_restantes INTEGER;
    v_tipo_alerta VARCHAR(50);
    v_titulo VARCHAR(200);
    v_mensaje TEXT;
    v_alertas_creadas INTEGER := 0;
    v_equipos_alertados INTEGER := 0;
BEGIN
    -- Iterar sobre equipos con planes activos
    FOR v_equipo_plan IN
        SELECT epm.*, e.nombre as equipo_nombre, e.cliente_id
        FROM equipos_planes_mantenimiento epm
        JOIN equipos_unidades e ON e.id = epm.equipo_id
        WHERE epm.activo = true
          AND epm.suspendido = false
          AND epm.proxima_fecha_mantenimiento IS NOT NULL
    LOOP
        -- Calcular días restantes
        v_dias_restantes := v_equipo_plan.proxima_fecha_mantenimiento - CURRENT_DATE;

        -- Determinar si necesita alerta
        v_tipo_alerta := NULL;

        IF v_dias_restantes < 0 THEN
            v_tipo_alerta := 'vencido';
            v_titulo := 'Mantenimiento VENCIDO';
            v_mensaje := format(
                'El mantenimiento del equipo %s está vencido por %s día(s). Fecha programada: %s',
                v_equipo_plan.equipo_nombre,
                ABS(v_dias_restantes),
                v_equipo_plan.proxima_fecha_mantenimiento
            );
        ELSIF v_dias_restantes <= v_equipo_plan.dias_alerta_anticipada THEN
            v_tipo_alerta := 'proximo';
            v_titulo := 'Mantenimiento próximo';
            v_mensaje := format(
                'El equipo %s requiere mantenimiento en %s día(s). Fecha programada: %s',
                v_equipo_plan.equipo_nombre,
                v_dias_restantes,
                v_equipo_plan.proxima_fecha_mantenimiento
            );
        END IF;

        -- Crear alerta si es necesario
        IF v_tipo_alerta IS NOT NULL THEN
            -- Verificar que no exista una alerta activa para este equipo_plan
            IF NOT EXISTS (
                SELECT 1 FROM mantenimiento_alertas
                WHERE equipo_plan_id = v_equipo_plan.id
                  AND estado IN ('activa', 'leida')
                  AND fecha_mantenimiento_programado = v_equipo_plan.proxima_fecha_mantenimiento
            ) THEN
                INSERT INTO mantenimiento_alertas (
                    equipo_plan_id,
                    equipo_id,
                    cliente_id,
                    tipo_alerta,
                    titulo,
                    mensaje,
                    fecha_mantenimiento_programado,
                    dias_restantes
                ) VALUES (
                    v_equipo_plan.id,
                    v_equipo_plan.equipo_id,
                    v_equipo_plan.cliente_id,
                    v_tipo_alerta,
                    v_titulo,
                    v_mensaje,
                    v_equipo_plan.proxima_fecha_mantenimiento,
                    v_dias_restantes
                );

                v_alertas_creadas := v_alertas_creadas + 1;
                v_equipos_alertados := v_equipos_alertados + 1;
            END IF;
        END IF;
    END LOOP;

    RETURN QUERY SELECT v_equipos_alertados, v_alertas_creadas;
END;
$$;


--
-- Name: FUNCTION generar_alertas_mantenimiento(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.generar_alertas_mantenimiento() IS 'Genera alertas automáticas para mantenimientos próximos o vencidos';


--
-- Name: generar_numero_instalacion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generar_numero_instalacion() RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  siguiente_numero integer;
  numero_instalacion text;
BEGIN
  siguiente_numero := nextval('instalaciones_numero_seq');
  numero_instalacion := 'INST-' || TO_CHAR(CURRENT_DATE, 'YYYY') || '-' || LPAD(siguiente_numero::text, 6, '0');
  RETURN numero_instalacion;
END;
$$;


