--
-- Name: generate_preparacion_numero(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_preparacion_numero() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    year_prefix VARCHAR(4);
    next_number INTEGER;
BEGIN
    IF NEW.numero IS NULL OR NEW.numero = '' THEN
        year_prefix := TO_CHAR(NOW(), 'YYYY');

        SELECT COALESCE(MAX(
            CAST(SUBSTRING(numero FROM 'PE-' || year_prefix || '-(\d+)') AS INTEGER)
        ), 0) + 1
        INTO next_number
        FROM preparacion_entregas
        WHERE numero LIKE 'PE-' || year_prefix || '-%';

        NEW.numero := 'PE-' || year_prefix || '-' || LPAD(next_number::TEXT, 4, '0');
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: generate_presupuesto_equipo_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_presupuesto_equipo_number() RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
    year_part TEXT;
    seq_num INTEGER;
    new_number TEXT;
BEGIN
    year_part := TO_CHAR(CURRENT_DATE, 'YYYY');

    SELECT COALESCE(MAX(
        CASE
            WHEN numero ~ ('^PE-' || year_part || '-[0-9]+$')
            THEN CAST(SUBSTRING(numero FROM 'PE-' || year_part || '-([0-9]+)$') AS INTEGER)
            ELSE 0
        END
    ), 0) + 1
    INTO seq_num
    FROM presupuestos_equipos;

    new_number := 'PE-' || year_part || '-' || LPAD(seq_num::TEXT, 4, '0');

    RETURN new_number;
END;
$_$;


--
-- Name: generate_presupuesto_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_presupuesto_number() RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  next_number INTEGER;
  year_suffix TEXT;
BEGIN
  year_suffix := TO_CHAR(CURRENT_DATE, 'YY');

  SELECT COALESCE(MAX(CAST(SUBSTRING(numero FROM 5) AS INTEGER)), 0) + 1
  INTO next_number
  FROM public.presupuestos
  WHERE numero LIKE 'PRES%';

  RETURN 'PRES' || LPAD(next_number::TEXT, 6, '0');
END;
$$;


