--
-- Name: get_contactos_laboratorio(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_contactos_laboratorio(p_laboratorio_id uuid) RETURNS TABLE(id uuid, nombre_completo text, email text[], telefono text[], cargo text, rol text, es_principal boolean)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        p.id,
        p.nombre_completo,
        p.email,
        p.telefono,
        p.cargo,
        pl.rol,
        pl.rol IN ('bioquimico_responsable', 'tecnico_principal') AS es_principal
    FROM personas_laboratorios pl
    JOIN personas p ON p.id = pl.persona_id
    WHERE pl.laboratorio_id = p_laboratorio_id
      AND pl.activo = true
      AND p.activo = true
    ORDER BY
        CASE pl.rol
            WHEN 'bioquimico_responsable' THEN 1
            WHEN 'tecnico_principal' THEN 2
            WHEN 'bioquimico' THEN 3
            WHEN 'tecnico' THEN 4
            ELSE 5
        END;
END;
$$;


