CREATE FUNCTION public.get_cotizacion_del_dia(p_tipo character varying DEFAULT 'oficial'::character varying) RETURNS TABLE(valor_compra numeric, valor_venta numeric, fecha date, tipo character varying, fuente character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    c.valor_compra,
    c.valor_venta,
    c.fecha,
    c.tipo::VARCHAR,
    c.fuente::VARCHAR
  FROM cotizaciones c
  WHERE c.tipo = p_tipo
  ORDER BY c.fecha DESC
  LIMIT 1;
END;
$$;


