--
-- Name: get_emails_para_envio(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_emails_para_envio(p_laboratorio_id uuid DEFAULT NULL::uuid, p_razon_social_id uuid DEFAULT NULL::uuid, p_tipo_envio text DEFAULT 'general'::text) RETURNS TABLE(persona_id uuid, nombre_completo text, email text, origen text)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    -- Si se especifica laboratorio
    IF p_laboratorio_id IS NOT NULL THEN
        RETURN QUERY
        SELECT DISTINCT ON (unnest_email)
            p.id AS persona_id,
            p.nombre_completo,
            unnest(p.email) AS email,
            'laboratorio'::text AS origen
        FROM personas_laboratorios pl
        JOIN personas p ON p.id = pl.persona_id
        CROSS JOIN LATERAL unnest(p.email) AS unnest_email
        WHERE pl.laboratorio_id = p_laboratorio_id
          AND pl.activo = true
          AND p.activo = true
          AND p.email IS NOT NULL
          AND array_length(p.email, 1) > 0
        ORDER BY unnest_email,
            CASE pl.rol
                WHEN 'bioquimico_responsable' THEN 1
                WHEN 'tecnico_principal' THEN 2
                ELSE 3
            END;
    -- Si se especifica razón social
    ELSIF p_razon_social_id IS NOT NULL THEN
        RETURN QUERY
        SELECT DISTINCT ON (unnest_email)
            p.id AS persona_id,
            p.nombre_completo,
            unnest(p.email) AS email,
            'razon_social'::text AS origen
        FROM personas_razones_sociales prs
        JOIN personas p ON p.id = prs.persona_id
        CROSS JOIN LATERAL unnest(p.email) AS unnest_email
        WHERE prs.razon_social_id = p_razon_social_id
          AND prs.activo = true
          AND p.activo = true
          AND p.email IS NOT NULL
          AND array_length(p.email, 1) > 0
          AND (
              p_tipo_envio = 'general'
              OR (p_tipo_envio = 'factura' AND prs.recibe_facturas = true)
              OR (p_tipo_envio = 'presupuesto' AND prs.recibe_presupuestos = true)
              OR (p_tipo_envio = 'tecnico' AND prs.tipo_relacion = 'contacto_tecnico')
          )
        ORDER BY unnest_email, prs.es_contacto_principal DESC;
    END IF;
END;
$$;


--
-- Name: FUNCTION get_emails_para_envio(p_laboratorio_id uuid, p_razon_social_id uuid, p_tipo_envio text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_emails_para_envio(p_laboratorio_id uuid, p_razon_social_id uuid, p_tipo_envio text) IS 'Obtiene emails para envío según laboratorio o razón social y tipo de comunicación';


--
-- Name: ina_get_or_create_conversation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ina_get_or_create_conversation(p1 uuid, p2 uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  conv_id UUID;
  a UUID := LEAST(p1, p2);
  b UUID := GREATEST(p1, p2);
BEGIN
  SELECT id INTO conv_id FROM ina_conversations
  WHERE participant_1 = a AND participant_2 = b;

  IF conv_id IS NULL THEN
    INSERT INTO ina_conversations (participant_1, participant_2, org_id)
    SELECT a, b, om.org_id
    FROM org_members om
    WHERE om.persona_id = p1
      AND om.org_id = (SELECT org_id FROM org_members WHERE persona_id = p2 AND org_id = om.org_id LIMIT 1)
    LIMIT 1
    RETURNING id INTO conv_id;
  END IF;

  UPDATE ina_conversations SET last_message_at = NOW() WHERE id = conv_id;

  RETURN conv_id;
END;
$$;


