--
-- Name: nea_liq_recalc(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nea_liq_recalc() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  liq_id uuid;
BEGIN
  IF (TG_OP = 'DELETE') THEN
    liq_id := OLD.liquidacion_id;
  ELSE
    liq_id := NEW.liquidacion_id;
  END IF;

  UPDATE nea_profesional_liquidaciones
  SET monto_pagado = COALESCE((
      SELECT SUM(monto) FROM nea_profesional_pagos WHERE liquidacion_id = liq_id
    ), 0),
    estado = CASE
      WHEN COALESCE((SELECT SUM(monto) FROM nea_profesional_pagos WHERE liquidacion_id = liq_id), 0) <= 0 THEN 'pendiente'
      WHEN COALESCE((SELECT SUM(monto) FROM nea_profesional_pagos WHERE liquidacion_id = liq_id), 0) >= monto_neto THEN 'pagado'
      ELSE 'parcial'
    END,
    updated_at = now()
  WHERE id = liq_id;

  IF (TG_OP = 'DELETE') THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


--
-- Name: next_vet_presupuesto_numero(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_vet_presupuesto_numero(p_org_id uuid) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  next_num INTEGER;
BEGIN
  SELECT COALESCE(MAX(CAST(SUBSTRING(numero FROM 4) AS INTEGER)), 0) + 1
  INTO next_num
  FROM vet_presupuestos
  WHERE org_id = p_org_id AND numero IS NOT NULL;
  RETURN 'PV-' || LPAD(next_num::TEXT, 4, '0');
END;
$$;


--
-- Name: obtener_permisos_usuario(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obtener_permisos_usuario(p_user_id uuid) RETURNS TABLE(modulo character varying, accion character varying, descripcion text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT DISTINCT pm.modulo, pm.accion, pm.descripcion
  FROM perfiles pf
  JOIN roles r ON pf.rol_id = r.id
  LEFT JOIN roles_permisos rp ON r.id = rp.rol_id
  LEFT JOIN permisos pm ON rp.permiso_id = pm.id
  WHERE pf.id = p_user_id
    AND (r.es_admin = true OR pm.id IS NOT NULL);
END;
$$;


--
-- Name: obtener_precio_compra(uuid, uuid, numeric, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obtener_precio_compra(p_producto_id uuid, p_proveedor_id uuid DEFAULT NULL::uuid, p_cantidad numeric DEFAULT 1, p_fecha date DEFAULT CURRENT_DATE) RETURNS TABLE(proveedor_id uuid, proveedor_nombre text, precio_unitario numeric, moneda character varying, lista_id uuid, lista_nombre character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        plp.proveedor_id,
        prov.nombre::TEXT,
        pli.precio_neto,
        plp.moneda,
        plp.id,
        plp.nombre
    FROM proveedor_lista_items pli
    JOIN proveedor_listas_precios plp ON plp.id = pli.lista_id
    JOIN proveedores prov ON prov.id = plp.proveedor_id
    WHERE pli.producto_id = p_producto_id
      AND pli.activo = true
      AND plp.estado = 'activa'
      AND plp.fecha_inicio <= p_fecha
      AND (plp.fecha_fin IS NULL OR plp.fecha_fin >= p_fecha)
      AND pli.cantidad_minima <= p_cantidad
      AND (p_proveedor_id IS NULL OR plp.proveedor_id = p_proveedor_id)
    ORDER BY pli.precio_neto ASC
    LIMIT 10;
END;
$$;


--
-- Name: FUNCTION obtener_precio_compra(p_producto_id uuid, p_proveedor_id uuid, p_cantidad numeric, p_fecha date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obtener_precio_compra(p_producto_id uuid, p_proveedor_id uuid, p_cantidad numeric, p_fecha date) IS 'Obtiene los mejores precios de compra vigentes para un producto, opcionalmente filtrado por proveedor.';


