--
-- Name: registrar_actividad(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_actividad() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Registrar creación
  IF (TG_OP = 'INSERT') THEN
    INSERT INTO public.actividad (
      usuario_nombre,
      accion,
      entidad_tipo,
      entidad_id,
      descripcion,
      datos_nuevos
    ) VALUES (
      COALESCE(current_setting('app.current_user_name', true), 'Sistema'),
      'crear',
      TG_TABLE_NAME,
      NEW.id,
      'Creó nuevo registro',
      to_jsonb(NEW)
    );
    RETURN NEW;
  END IF;

  -- Registrar actualización
  IF (TG_OP = 'UPDATE') THEN
    INSERT INTO public.actividad (
      usuario_nombre,
      accion,
      entidad_tipo,
      entidad_id,
      descripcion,
      datos_anteriores,
      datos_nuevos
    ) VALUES (
      COALESCE(current_setting('app.current_user_name', true), 'Sistema'),
      'actualizar',
      TG_TABLE_NAME,
      NEW.id,
      'Actualizó registro',
      to_jsonb(OLD),
      to_jsonb(NEW)
    );
    RETURN NEW;
  END IF;

  -- Registrar eliminación
  IF (TG_OP = 'DELETE') THEN
    INSERT INTO public.actividad (
      usuario_nombre,
      accion,
      entidad_tipo,
      entidad_id,
      descripcion,
      datos_anteriores
    ) VALUES (
      COALESCE(current_setting('app.current_user_name', true), 'Sistema'),
      'eliminar',
      TG_TABLE_NAME,
      OLD.id,
      'Eliminó registro',
      to_jsonb(OLD)
    );
    RETURN OLD;
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: registrar_cambio_estado_envio(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_cambio_estado_envio() RETURNS trigger
