--
-- Name: registrar_cambio_precio(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_cambio_precio() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Si cambió el precio de costo
    IF OLD.precio_costo IS DISTINCT FROM NEW.precio_costo THEN
        INSERT INTO public.historial_precios (
            producto_id, precio_anterior, precio_nuevo, tipo_precio, motivo_cambio
        ) VALUES (
            NEW.id, OLD.precio_costo, NEW.precio_costo, 'costo', 'Actualización de precio de costo'
        );
    END IF;

    -- Si cambió el precio de venta
    IF OLD.precio_venta IS DISTINCT FROM NEW.precio_venta THEN
        INSERT INTO public.historial_precios (
            producto_id, precio_anterior, precio_nuevo, tipo_precio, motivo_cambio
        ) VALUES (
            NEW.id, OLD.precio_venta, NEW.precio_venta, 'venta', 'Actualización de precio de venta'
        );
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: registrar_cambio_servicio(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_cambio_servicio() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Log estado changes
  IF OLD.estado IS DISTINCT FROM NEW.estado THEN
    INSERT INTO servicios_historial (servicio_id, campo_modificado, valor_anterior, valor_nuevo)
    VALUES (NEW.id, 'estado', OLD.estado, NEW.estado);
  END IF;

  -- Log tecnico changes
  IF OLD.tecnico IS DISTINCT FROM NEW.tecnico THEN
    INSERT INTO servicios_historial (servicio_id, campo_modificado, valor_anterior, valor_nuevo)
    VALUES (NEW.id, 'tecnico', OLD.tecnico, NEW.tecnico);
  END IF;

  -- Log diagnostico changes
  IF OLD.diagnostico IS DISTINCT FROM NEW.diagnostico THEN
    INSERT INTO servicios_historial (servicio_id, campo_modificado, valor_anterior, valor_nuevo)
    VALUES (NEW.id, 'diagnostico', OLD.diagnostico, NEW.diagnostico);
  END IF;

  -- Log monto_servicio changes
  IF OLD.monto_servicio IS DISTINCT FROM NEW.monto_servicio THEN
    INSERT INTO servicios_historial (servicio_id, campo_modificado, valor_anterior, valor_nuevo)
    VALUES (NEW.id, 'monto_servicio', OLD.monto_servicio::TEXT, NEW.monto_servicio::TEXT);
  END IF;

  -- Log monto_insumos changes
  IF OLD.monto_insumos IS DISTINCT FROM NEW.monto_insumos THEN
    INSERT INTO servicios_historial (servicio_id, campo_modificado, valor_anterior, valor_nuevo)
    VALUES (NEW.id, 'monto_insumos', OLD.monto_insumos::TEXT, NEW.monto_insumos::TEXT);
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: registrar_cambio_tarea(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_cambio_tarea() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  usuario_nombre_var VARCHAR(255);
BEGIN
  -- Obtener nombre de usuario actual (si está disponible)
  SELECT email INTO usuario_nombre_var FROM auth.users WHERE id = auth.uid();

  -- Registrar cambios importantes
  IF TG_OP = 'INSERT' THEN
    INSERT INTO tareas_historial (tarea_id, accion, descripcion, usuario_id, usuario_nombre)
    VALUES (NEW.id, 'creada', 'Tarea creada', NEW.creado_por, NEW.creado_por_nombre);

  ELSIF TG_OP = 'UPDATE' THEN
    -- Cambio de estado
    IF OLD.estado IS DISTINCT FROM NEW.estado THEN
      INSERT INTO tareas_historial (tarea_id, accion, descripcion, campo_modificado, valor_anterior, valor_nuevo, usuario_id, usuario_nombre)
      VALUES (NEW.id, 'estado_cambio',
              'Estado cambió de "' || OLD.estado || '" a "' || NEW.estado || '"',
              'estado', OLD.estado, NEW.estado, auth.uid(), usuario_nombre_var);
    END IF;

    -- Cambio de asignación
    IF OLD.asignado_a IS DISTINCT FROM NEW.asignado_a THEN
      INSERT INTO tareas_historial (tarea_id, accion, descripcion, campo_modificado, valor_anterior, valor_nuevo, usuario_id, usuario_nombre)
      VALUES (NEW.id, 'asignada',
              'Asignada a ' || COALESCE(NEW.asignado_a_nombre, 'Sin asignar'),
              'asignado_a', COALESCE(OLD.asignado_a_nombre, ''), COALESCE(NEW.asignado_a_nombre, ''),
              auth.uid(), usuario_nombre_var);
    END IF;

    -- Cambio de prioridad
    IF OLD.prioridad IS DISTINCT FROM NEW.prioridad THEN
      INSERT INTO tareas_historial (tarea_id, accion, descripcion, campo_modificado, valor_anterior, valor_nuevo, usuario_id, usuario_nombre)
      VALUES (NEW.id, 'prioridad_cambio',
              'Prioridad cambió de "' || OLD.prioridad || '" a "' || NEW.prioridad || '"',
              'prioridad', OLD.prioridad, NEW.prioridad, auth.uid(), usuario_nombre_var);
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


