--
-- Name: registrar_movimiento_serial(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_movimiento_serial() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- Si cambió el depósito o bin, registrar movimiento
    IF OLD.deposito_id IS DISTINCT FROM NEW.deposito_id OR
       OLD.bin_id IS DISTINCT FROM NEW.bin_id OR
       OLD.estado IS DISTINCT FROM NEW.estado THEN

      INSERT INTO seriales_historial (
        serial_id,
        tipo_movimiento,
        desde_deposito_id,
        hacia_deposito_id,
        desde_bin_id,
        hacia_bin_id,
        cliente_id
      ) VALUES (
        NEW.id,
        CASE
          WHEN NEW.estado = 'vendido' THEN 'venta'
          WHEN NEW.estado = 'comodato' THEN 'comodato'
          WHEN NEW.estado = 'servicio_tecnico' THEN 'servicio_tecnico'
          ELSE 'transferencia'
        END,
        OLD.deposito_id,
        NEW.deposito_id,
        OLD.bin_id,
        NEW.bin_id,
        NEW.cliente_id
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: reset_demo_bella_vita(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_demo_bella_vita() RETURNS void
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_org UUID := 'b0000000-0000-0000-0000-000000000001';
  v_prof UUID;
  v_prof2 UUID;
  v_prof3 UUID;
  v_cab UUID;
  v_svc UUID;
  v_svc_precio NUMERIC;
  v_svc_dur INT;
  v_cli UUID;
  v_cli_factura UUID;
  v_tid UUID;
  v_fid UUID;
  v_conv UUID;
  -- Client personas from org_contacts
  clients UUID[];
  client_names TEXT[];
  client_phones TEXT[];
BEGIN
  -- ============================================================
  -- 1. DELETE all mutable demo data
  -- ============================================================
  DELETE FROM nea_actividad WHERE org_id = v_org;
  DELETE FROM contenido_piezas WHERE org_id = v_org;
  DELETE FROM nea_conversaciones WHERE org_id = v_org;  -- cascades to nea_mensajes
  DELETE FROM nea_sesiones WHERE org_id = v_org;
  DELETE FROM cobros WHERE org_id = v_org;
  DELETE FROM facturas WHERE org_id = v_org;
  DELETE FROM nea_turnos WHERE org_id = v_org;
  -- Reset campaign stats
  UPDATE email_campanas SET
    total_enviados = CASE WHEN estado = 'enviada' THEN 8 ELSE 0 END,
    total_fallidos = 0,
    total_abiertos = CASE WHEN estado = 'enviada' THEN 5 ELSE 0 END,
    total_clicks = CASE WHEN estado = 'enviada' THEN 2 ELSE 0 END,
    total_unsubs = 0
  WHERE org_id = v_org;

  -- ============================================================
  -- 2. Collect references
  -- ============================================================
  SELECT ARRAY_AGG(oc.persona_id ORDER BY p.nombre)
  INTO clients
  FROM org_contacts oc
  JOIN personas p ON p.id = oc.persona_id
  WHERE oc.org_id = v_org AND oc.tipo = 'cliente';

  SELECT ARRAY_AGG(p.nombre || ' ' || COALESCE(p.apellido,'') ORDER BY p.nombre)
  INTO client_names
  FROM org_contacts oc
  JOIN personas p ON p.id = oc.persona_id
  WHERE oc.org_id = v_org AND oc.tipo = 'cliente';

  SELECT ARRAY_AGG(COALESCE(p.telefono,'2236001001') ORDER BY p.nombre)
  INTO client_phones
  FROM org_contacts oc
  JOIN personas p ON p.id = oc.persona_id
  WHERE oc.org_id = v_org AND oc.tipo = 'cliente';

  IF clients IS NULL OR array_length(clients, 1) < 3 THEN
    RAISE NOTICE 'Not enough client data for bella-vita demo';
    RETURN;
  END IF;

  SELECT id INTO v_prof FROM nea_profesionales WHERE org_id = v_org LIMIT 1;
  SELECT id INTO v_prof2 FROM nea_profesionales WHERE org_id = v_org OFFSET 1 LIMIT 1;
  SELECT id INTO v_prof3 FROM nea_profesionales WHERE org_id = v_org OFFSET 2 LIMIT 1;
  SELECT id INTO v_cab FROM nea_cabinas WHERE org_id = v_org LIMIT 1;

  IF v_prof IS NULL OR v_cab IS NULL THEN
    RAISE NOTICE 'No professionals or cabinas found';
    RETURN;
  END IF;

  -- ============================================================
  -- 3. TURNOS: yesterday completed, today mix, tomorrow upcoming
  -- ============================================================

  -- Yesterday: 3 completed with payments
  FOR i IN 0..2 LOOP
    SELECT id, precio, duracion_min INTO v_svc, v_svc_precio, v_svc_dur
    FROM nea_servicios WHERE org_id = v_org AND activo = true OFFSET i LIMIT 1;
    v_cli := clients[i + 1];
    v_cli_factura := (SELECT id FROM clientes WHERE org_id = v_org OFFSET i LIMIT 1);

    INSERT INTO nea_turnos (org_id, cliente_id, profesional_id, servicio_id, cabina_id, fecha, hora_inicio, hora_fin, estado, origen)
    VALUES (v_org, v_cli, v_prof, v_svc,
      (SELECT id FROM nea_cabinas WHERE org_id = v_org OFFSET i%5 LIMIT 1),
      CURRENT_DATE - 1, TIME '09:00' + i * INTERVAL '90 min', TIME '09:00' + i * INTERVAL '90 min' + v_svc_dur * INTERVAL '1 min',
      'completado', 'admin')
    RETURNING id INTO v_tid;

    INSERT INTO nea_sesiones (org_id, turno_id, profesional_id, servicio_id, notas_profesional, satisfaccion_cliente)
    VALUES (v_org, v_tid, v_prof, v_svc, 'Sesion sin novedades. Clienta conforme.', 5);

    INSERT INTO facturas (org_id, cliente_id, tipo_factura, nro_factura, fecha_emision, total, subtotal, estado)
    VALUES (v_org, COALESCE(v_cli_factura, v_cli), CASE WHEN i=0 THEN 'B' ELSE 'IVR' END,
      'NEA-' || LPAD((i+1)::text, 6, '0'), CURRENT_DATE - 1, v_svc_precio, v_svc_precio, 'pagada')
    RETURNING id INTO v_fid;

    INSERT INTO cobros (org_id, factura_id, monto, fecha_pago, metodo_pago)
    VALUES (v_org, v_fid, v_svc_precio, CURRENT_DATE - 1,
      CASE i WHEN 0 THEN 'tarjeta' WHEN 1 THEN 'efectivo' ELSE 'transferencia' END);
  END LOOP;

  -- Today: 4 completed (2 paid, 2 pending) + 2 upcoming
  FOR i IN 0..5 LOOP
    SELECT id, precio, duracion_min INTO v_svc, v_svc_precio, v_svc_dur
    FROM nea_servicios WHERE org_id = v_org AND activo = true OFFSET (i % 14) LIMIT 1;
    v_cli := clients[(i % array_length(clients, 1)) + 1];
    v_cli_factura := (SELECT id FROM clientes WHERE org_id = v_org OFFSET (i % 8) LIMIT 1);

    INSERT INTO nea_turnos (org_id, cliente_id, profesional_id, servicio_id, cabina_id, fecha, hora_inicio, hora_fin, estado, origen)
    VALUES (v_org, v_cli,
      CASE WHEN i < 2 THEN v_prof WHEN i < 4 THEN COALESCE(v_prof2, v_prof) ELSE COALESCE(v_prof3, v_prof) END,
      v_svc,
      (SELECT id FROM nea_cabinas WHERE org_id = v_org OFFSET i%5 LIMIT 1),
      CURRENT_DATE, TIME '09:00' + i * INTERVAL '75 min', TIME '09:00' + i * INTERVAL '75 min' + v_svc_dur * INTERVAL '1 min',
      CASE WHEN i < 4 THEN 'completado' WHEN i = 4 THEN 'confirmado' ELSE 'reservado' END,
      CASE WHEN i = 5 THEN 'online' ELSE 'admin' END)
    RETURNING id INTO v_tid;

    IF i < 4 THEN
      INSERT INTO nea_sesiones (org_id, turno_id, profesional_id, servicio_id, notas_profesional, satisfaccion_cliente)
      VALUES (v_org, v_tid, v_prof, v_svc, 'Sesion completada correctamente.', CASE WHEN i < 3 THEN 5 ELSE 4 END);

      INSERT INTO facturas (org_id, cliente_id, tipo_factura, nro_factura, fecha_emision, total, subtotal, estado)
      VALUES (v_org, COALESCE(v_cli_factura, v_cli),
        CASE WHEN i < 2 THEN 'B' ELSE 'IVR' END,
        'NEA-' || LPAD((i + 4)::text, 6, '0'), CURRENT_DATE, v_svc_precio, v_svc_precio,
        CASE WHEN i < 2 THEN 'pagada' ELSE 'pendiente' END)
      RETURNING id INTO v_fid;

      IF i < 2 THEN
        INSERT INTO cobros (org_id, factura_id, monto, fecha_pago, metodo_pago)
        VALUES (v_org, v_fid, v_svc_precio, CURRENT_DATE,
          CASE i WHEN 0 THEN 'tarjeta' ELSE 'efectivo' END);
      END IF;
    END IF;
  END LOOP;

  -- Tomorrow: 4 upcoming
  FOR i IN 0..3 LOOP
    SELECT id, precio, duracion_min INTO v_svc, v_svc_precio, v_svc_dur
    FROM nea_servicios WHERE org_id = v_org AND activo = true OFFSET (i + 4) LIMIT 1;
    v_cli := clients[(i + 3) % array_length(clients, 1) + 1];

    INSERT INTO nea_turnos (org_id, cliente_id, profesional_id, servicio_id, cabina_id, fecha, hora_inicio, hora_fin, estado, origen)
    VALUES (v_org, v_cli,
      CASE WHEN i < 2 THEN v_prof ELSE COALESCE(v_prof2, v_prof) END,
      v_svc,
      (SELECT id FROM nea_cabinas WHERE org_id = v_org OFFSET i%5 LIMIT 1),
      CURRENT_DATE + 1, TIME '09:30' + i * INTERVAL '80 min', TIME '09:30' + i * INTERVAL '80 min' + v_svc_dur * INTERVAL '1 min',
      CASE WHEN i < 2 THEN 'confirmado' ELSE 'reservado' END, 'online');
  END LOOP;

  -- Historical facturas (last 30 days for reports)
  FOR d IN 3..28 LOOP
    IF d % 2 = 0 THEN
      SELECT id, precio INTO v_svc, v_svc_precio
      FROM nea_servicios WHERE org_id = v_org AND activo = true OFFSET (d % 14) LIMIT 1;
      v_cli := clients[(d % array_length(clients, 1)) + 1];
      v_cli_factura := (SELECT id FROM clientes WHERE org_id = v_org OFFSET (d % 8) LIMIT 1);

      INSERT INTO facturas (org_id, cliente_id, tipo_factura, nro_factura, fecha_emision, total, subtotal, estado)
      VALUES (v_org, COALESCE(v_cli_factura, v_cli),
        CASE WHEN d%3=0 THEN 'B' ELSE 'IVR' END,
        'NEA-H' || LPAD(d::text, 4, '0'), CURRENT_DATE - d, v_svc_precio, v_svc_precio, 'pagada')
      RETURNING id INTO v_fid;

      INSERT INTO cobros (org_id, factura_id, monto, fecha_pago, metodo_pago)
      VALUES (v_org, v_fid, v_svc_precio, CURRENT_DATE - d,
        CASE WHEN d%3=0 THEN 'efectivo' WHEN d%3=1 THEN 'tarjeta' ELSE 'transferencia' END);
    END IF;
  END LOOP;

  -- ============================================================
  -- 4. CONVERSACIONES + MENSAJES
  -- ============================================================

