    NOW() - INTERVAL '25 min', 'Dale perfecto, nos vemos!', 0)
  RETURNING id INTO v_conv;

  INSERT INTO nea_mensajes (conversacion_id, org_id, direccion, origen, tipo, contenido, estado, created_at) VALUES
