--
-- Name: set_instalacion_numero(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_instalacion_numero() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.numero IS NULL OR NEW.numero = '' THEN
    NEW.numero := generar_numero_instalacion();
  END IF;
  RETURN NEW;
END;
$$;


