--
-- Name: tiene_permiso(uuid, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tiene_permiso(p_user_id uuid, p_modulo character varying, p_accion character varying) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_es_admin BOOLEAN;
  v_tiene_permiso BOOLEAN;
BEGIN
  -- Verificar si es admin
  SELECT r.es_admin INTO v_es_admin
  FROM perfiles p
  JOIN roles r ON p.rol_id = r.id
  WHERE p.id = p_user_id;

  -- Si es admin, tiene todos los permisos
  IF v_es_admin THEN
    RETURN true;
  END IF;

  -- Verificar permiso específico
  SELECT EXISTS (
    SELECT 1
    FROM perfiles pf
    JOIN roles_permisos rp ON pf.rol_id = rp.rol_id
    JOIN permisos pm ON rp.permiso_id = pm.id
    WHERE pf.id = p_user_id
      AND pm.modulo = p_modulo
      AND pm.accion = p_accion
  ) INTO v_tiene_permiso;

  RETURN COALESCE(v_tiene_permiso, false);
END;
$$;


--
-- Name: trigger_actualizar_producto_proveedor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_actualizar_producto_proveedor() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_proveedor_id UUID;
BEGIN
    -- Obtener proveedor de la lista
    SELECT proveedor_id INTO v_proveedor_id
    FROM proveedor_listas_precios
    WHERE id = NEW.lista_id;

    -- Insertar o actualizar producto_proveedores
    INSERT INTO producto_proveedores (
        producto_id, proveedor_id, codigo_proveedor, nombre_proveedor,
        ultimo_precio, ultima_moneda, ultima_actualizacion, ultima_lista_id
    )
    SELECT
        NEW.producto_id,
        v_proveedor_id,
        NEW.codigo_proveedor,
        NEW.nombre_proveedor,
        NEW.precio_neto,
        plp.moneda,
        CURRENT_DATE,
        NEW.lista_id
    FROM proveedor_listas_precios plp
    WHERE plp.id = NEW.lista_id
    ON CONFLICT (producto_id, proveedor_id) DO UPDATE SET
        codigo_proveedor = COALESCE(EXCLUDED.codigo_proveedor, producto_proveedores.codigo_proveedor),
        nombre_proveedor = COALESCE(EXCLUDED.nombre_proveedor, producto_proveedores.nombre_proveedor),
        ultimo_precio = EXCLUDED.ultimo_precio,
        ultima_moneda = EXCLUDED.ultima_moneda,
        ultima_actualizacion = EXCLUDED.ultima_actualizacion,
        ultima_lista_id = EXCLUDED.ultima_lista_id,
        updated_at = NOW();

    RETURN NEW;
END;
$$;


--
-- Name: trigger_registrar_cambio_precio_proveedor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_registrar_cambio_precio_proveedor() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' AND OLD.precio_costo IS DISTINCT FROM NEW.precio_costo THEN
        INSERT INTO proveedor_historial_precios (
            proveedor_id, producto_id, lista_id,
            precio_anterior, precio_nuevo, moneda, motivo
        )
        SELECT
            plp.proveedor_id,
            NEW.producto_id,
            NEW.lista_id,
            OLD.precio_costo,
            NEW.precio_costo,
            plp.moneda,
            'actualizacion'
        FROM proveedor_listas_precios plp
        WHERE plp.id = NEW.lista_id;
    ELSIF TG_OP = 'INSERT' THEN
        INSERT INTO proveedor_historial_precios (
            proveedor_id, producto_id, lista_id,
            precio_anterior, precio_nuevo, moneda, motivo
        )
        SELECT
            plp.proveedor_id,
            NEW.producto_id,
            NEW.lista_id,
            NULL,
            NEW.precio_costo,
            plp.moneda,
            'nueva_lista'
        FROM proveedor_listas_precios plp
        WHERE plp.id = NEW.lista_id;
    END IF;

    RETURN NEW;
END;
$$;


