--
-- Name: user_has_role(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_has_role(required_role text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM app_users
    WHERE id = auth.uid()::uuid
      AND (role = required_role OR role = 'admin')
  );
$$;


--
-- Name: validar_asiento_balanceado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validar_asiento_balanceado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  total_debe DECIMAL(15,2);
  total_haber DECIMAL(15,2);
BEGIN
  SELECT
    COALESCE(SUM(debe), 0),
    COALESCE(SUM(haber), 0)
  INTO total_debe, total_haber
  FROM asientos_items
  WHERE asiento_id = NEW.asiento_id;

  UPDATE asientos_contables
  SET
    total_debe = total_debe,
    total_haber = total_haber,
    updated_at = now()
  WHERE id = NEW.asiento_id;

  RETURN NEW;
END;
$$;


