    CONSTRAINT pedidos_estado_check CHECK ((estado = ANY (ARRAY['borrador'::text, 'pendiente'::text, 'confirmado'::text, 'pagado'::text, 'en_preparacion'::text, 'procesando'::text, 'preparando'::text, 'listo'::text, 'enviado'::text, 'entregado'::text, 'cancelado'::text]))),
