--
-- Name: actividad_reciente; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.actividad_reciente AS
 SELECT id,
    usuario_id,
    usuario_nombre,
    accion,
    entidad_tipo,
    entidad_id,
    entidad_nombre,
    descripcion,
    datos_anteriores,
    datos_nuevos,
    metadata,
    visible_cliente,
    importante,
    created_at,
        CASE entidad_tipo
            WHEN 'envio'::text THEN ( SELECT envios.numero_seguimiento
               FROM public.envios
              WHERE (envios.id = a.entidad_id))
            WHEN 'pedido'::text THEN ( SELECT pedidos.numero
               FROM public.pedidos
              WHERE (pedidos.id = a.entidad_id))
            ELSE NULL::text
        END AS entidad_numero
   FROM public.actividad a
  ORDER BY created_at DESC
 LIMIT 100;


--
-- Name: VIEW actividad_reciente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.actividad_reciente IS 'Últimas 100 actividades del sistema';


