--
-- Name: clientes_insumos; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.clientes_insumos AS
 SELECT r.cliente_id,
    ri.producto_id,
    sum(ri.cantidad) AS total_comprado
   FROM (public.remitos r
     JOIN public.remitos_items ri ON ((r.id = ri.remito_id)))
  GROUP BY r.cliente_id, ri.producto_id;


