--
-- Name: comprobante_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.comprobante_items (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    comprobante_id uuid NOT NULL,
    producto_id uuid,
    codigo text,
    descripcion text NOT NULL,
    cantidad numeric(12,4) DEFAULT 1 NOT NULL,
    unidad text DEFAULT 'unidad'::text,
    precio_unitario numeric(12,4) NOT NULL,
    bonificacion_pct numeric(5,2) DEFAULT 0,
    alicuota_iva numeric(5,2) DEFAULT 21 NOT NULL,
    subtotal numeric(12,2) GENERATED ALWAYS AS (((cantidad * precio_unitario) * ((1)::numeric - (bonificacion_pct / (100)::numeric)))) STORED,
    iva numeric(12,2) GENERATED ALWAYS AS (((((cantidad * precio_unitario) * ((1)::numeric - (bonificacion_pct / (100)::numeric))) * alicuota_iva) / (100)::numeric)) STORED,
    created_at timestamp with time zone DEFAULT now()
);


