    CONSTRAINT comprobantes_tipo_check CHECK ((tipo = ANY (ARRAY['A'::text, 'B'::text, 'C'::text, 'NC_A'::text, 'NC_B'::text, 'NC_C'::text, 'ND_A'::text, 'ND_B'::text, 'ND_C'::text])))
