   Las tentativas deben poder listarse/barrerse si la oportunidad se descarta.';


--
-- Name: comprobantes_completos; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.comprobantes_completos AS
 SELECT c.id,
    c.org_id,
    c.tipo,
    c.tipo_codigo,
    c.punto_venta,
    c.numero,
    c.fecha,
    c.cliente_id,
    c.cliente_nombre,
    c.cliente_doc_tipo,
    c.cliente_doc_nro,
    c.cliente_condicion_iva,
    c.cliente_domicilio,
    c.concepto,
    c.fecha_servicio_desde,
    c.fecha_servicio_hasta,
    c.fecha_vto_pago,
    c.imp_neto,
    c.imp_iva,
    c.imp_total,
    c.imp_tot_conc,
    c.imp_op_ex,
    c.imp_trib,
    c.moneda,
    c.cotizacion,
    c.cae,
    c.cae_vto,
    c.estado,
    c.afip_resultado,
    c.afip_observaciones,
    c.servicio_id,
    c.comprobante_asociado_id,
    c.notas,
    c.created_at,
    c.updated_at,
    p.nombre AS cliente_persona_nombre,
    p.email AS cliente_email,
    p.telefono AS cliente_telefono
   FROM ((public.comprobantes c
     LEFT JOIN public.org_contacts oc ON ((oc.id = c.cliente_id)))
     LEFT JOIN public.personas p ON ((p.id = oc.persona_id)));


