--
-- Name: envios_con_resumen; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.envios_con_resumen AS
 SELECT e.id,
    e.numero_seguimiento,
    e.pedido_id,
    e.cliente_id,
    e.cliente_nombre,
    e.transporte_id,
    e.estado,
    e.tipo_envio,
    e.direccion_origen,
    e.direccion_destino,
    e.fecha_despacho,
    e.fecha_entrega_estimada,
    e.fecha_entrega_real,
    e.peso,
    e.dimensiones,
    e.costo_envio,
    e.tracking_externo_id,
    e.url_seguimiento,
    e.observaciones,
    e.metadata,
    e.created_at,
    e.updated_at,
    t.nombre AS transporte_nombre,
    t.tipo AS transporte_tipo,
    ( SELECT count(*) AS count
           FROM public.envios_items
          WHERE (envios_items.envio_id = e.id)) AS total_items,
    ( SELECT count(*) AS count
           FROM public.envios_items
          WHERE ((envios_items.envio_id = e.id) AND (envios_items.diferencia = true))) AS items_con_diferencia,
    ( SELECT count(*) AS count
           FROM public.comentarios
          WHERE ((comentarios.entidad_tipo = 'envio'::text) AND (comentarios.entidad_id = e.id))) AS total_comentarios,
    ( SELECT count(*) AS count
           FROM public.comentarios
          WHERE ((comentarios.entidad_tipo = 'envio'::text) AND (comentarios.entidad_id = e.id) AND (comentarios.requiere_accion = true))) AS comentarios_pendientes,
    (EXISTS ( SELECT 1
           FROM public.envios_items
          WHERE ((envios_items.envio_id = e.id) AND (envios_items.diferencia = true)))) AS tiene_diferencias,
    GREATEST(e.updated_at, COALESCE(( SELECT max(comentarios.created_at) AS max
           FROM public.comentarios
          WHERE ((comentarios.entidad_tipo = 'envio'::text) AND (comentarios.entidad_id = e.id))), e.updated_at), COALESCE(( SELECT max(historial_estados.created_at) AS max
           FROM public.historial_estados
          WHERE ((historial_estados.entidad_tipo = 'envio'::text) AND (historial_estados.entidad_id = e.id))), e.updated_at)) AS ultima_actividad
   FROM (public.envios e
     LEFT JOIN public.transportes t ON ((e.transporte_id = t.id)));


--
-- Name: VIEW envios_con_resumen; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.envios_con_resumen IS 'Vista de envíos con información resumida y contadores';


