--
-- Name: facturacion_mensual; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.facturacion_mensual AS
 SELECT org_id,
    date_trunc('month'::text, (fecha)::timestamp with time zone) AS mes,
    tipo,
    count(*) AS cantidad,
    sum(imp_total) AS total,
    sum(imp_iva) AS total_iva
   FROM public.comprobantes
  WHERE (estado = 'autorizado'::text)
  GROUP BY org_id, (date_trunc('month'::text, (fecha)::timestamp with time zone)), tipo;


--
-- Name: facturas; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.facturas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    cliente_id uuid,
    fecha_emision date DEFAULT CURRENT_DATE,
    total numeric NOT NULL,
    estado text DEFAULT 'pendiente'::text,
    tipo_factura text DEFAULT 'IVR'::text,
    comentarios jsonb DEFAULT '[]'::jsonb,
    created_at timestamp with time zone DEFAULT now(),
    fecha_vencimiento date,
    forma_pago character varying(50),
    tipo_operacion character varying(20),
    nro_factura character varying(20),
    iva numeric(15,2) DEFAULT 0,
    subtotal numeric(15,2),
    total_pagado numeric(15,2) DEFAULT 0,
    punto_venta character varying(5) DEFAULT '0001'::character varying,
    cae character varying(14),
    cae_vto date,
    afip_resultado jsonb,
    afip_codigo_autorizacion character varying(20),
    afip_fecha_autorizacion timestamp with time zone,
    afip_qr_url text,
    afip_status character varying(20) DEFAULT 'pendiente'::character varying,
    detalles jsonb,
    saldo_pendiente numeric GENERATED ALWAYS AS ((total - COALESCE(total_pagado, (0)::numeric))) STORED,
    saldo_favor_contabilizado numeric(12,2) DEFAULT 0,
    afip_errores jsonb,
    afip_observaciones jsonb,
    qr_data text,
    moneda character varying(3) DEFAULT 'PES'::character varying,
    cotizacion numeric(18,6) DEFAULT 1,
    pedido_origen_id uuid,
    presupuesto_origen_id uuid,
    org_id uuid NOT NULL,
    CONSTRAINT facturas_estado_check CHECK ((estado = ANY (ARRAY['pendiente'::text, 'pagada'::text, 'vencida'::text, 'parcial'::text, 'anulada'::text]))),
    CONSTRAINT facturas_tipo_factura_check CHECK ((tipo_factura = ANY (ARRAY['A'::text, 'B'::text, 'C'::text, 'IVR'::text]))),
    CONSTRAINT facturas_tipo_operacion_check CHECK (((tipo_operacion)::text = ANY (ARRAY[('venta'::character varying)::text, ('servicio'::character varying)::text, ('nota_credito'::character varying)::text])))
);


--
