    activo boolean DEFAULT true
);


--
-- Name: featured_equipos_completa; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.featured_equipos_completa AS
 SELECT fe.id,
    fe.equipo_id,
    fe.posicion,
    fe.badge_text,
    fe.badge_color,
    fe.division AS featured_division,
    fe.custom_features,
    fe.activo,
    fe.created_at AS featured_created_at,
    fe.updated_at AS featured_updated_at,
    ec.marca,
    ec.modelo,
    ec.tipo,
    ec.categoria,
    ec.utilidad,
    ec.division AS equipo_division,
    ec.imagen_url,
    ec.detalle,
    ec.especificaciones,
    ec.disponible,
    ec.orden AS equipo_orden,
    ec.precio,
    ec.precio_dolar,
    ec.precio_pesos,
    ec.moneda,
    ec.iva,
    ec.producto_id,
    ec.created_at AS equipo_created_at,
    ec.updated_at AS equipo_updated_at
   FROM (public.featured_equipos fe
     JOIN public.equipos_catalogo ec ON ((fe.equipo_id = ec.id)))
  WHERE (fe.activo = true);


--
-- Name: featured_equipos_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.featured_equipos_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


