    es_placeholder boolean DEFAULT false NOT NULL,
    placeholder_descripcion text,
    estado_compra text DEFAULT 'en_stock'::text NOT NULL,
    fecha_pedido timestamp with time zone,
    fecha_estimada_llegada timestamp with time zone,
    fecha_recibido timestamp with time zone,
    CONSTRAINT instalaciones_items_estado_compra_check CHECK ((estado_compra = ANY (ARRAY['en_stock'::text, 'por_pedir'::text, 'pedido'::text, 'en_camino'::text, 'recibido'::text]))),
    CONSTRAINT instalaciones_items_estado_reserva_check CHECK ((estado_reserva = ANY (ARRAY['pendiente'::text, 'reservado'::text, 'entregado'::text, 'utilizado'::text, 'devuelto'::text]))),
    CONSTRAINT instalaciones_items_placeholder_has_desc CHECK (((es_placeholder = false) OR (placeholder_descripcion IS NOT NULL))),
    CONSTRAINT instalaciones_items_placeholder_no_fk CHECK (((es_placeholder = false) OR ((equipo_unidad_id IS NULL) AND (producto_id IS NULL)))),
    CONSTRAINT instalaciones_items_real_has_fk CHECK (((es_placeholder = true) OR ((tipo_item = ANY (ARRAY['equipo_principal'::text, 'equipo_adicional'::text])) AND (equipo_unidad_id IS NOT NULL)) OR ((tipo_item = ANY (ARRAY['insumo'::text, 'material'::text, 'herramienta'::text])) AND (producto_id IS NOT NULL)))),
    CONSTRAINT instalaciones_items_tipo_item_check CHECK ((tipo_item = ANY (ARRAY['equipo_principal'::text, 'equipo_adicional'::text, 'material'::text, 'insumo'::text, 'herramienta'::text])))
);


