--
-- Name: instalaciones_completas; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.instalaciones_completas AS
 SELECT i.id,
    i.numero,
    i.cliente_id,
    i.presupuesto_id,
    i.pedido_id,
    i.estado,
    i.fecha_planificada,
    i.fecha_inicio_real,
    i.fecha_finalizacion_real,
    i.fecha_vencimiento_garantia,
    i.direccion_instalacion,
    i.ubicacion_tipo_id,
    i.piso,
    i.sector,
    i.observaciones_ubicacion,
    i.equipo_id,
    i.tipo_equipo_id,
    i.descripcion_equipo,
    i.tecnico_asignado_id,
    i.tecnico_asignado_nombre,
    i.tecnicos_adicionales,
    i.costo_mano_obra,
    i.costo_materiales,
    i.costo_total,
    i.checklist_pre_instalacion,
    i.checklist_post_instalacion,
    i.certificados_requeridos,
    i.notas_planificacion,
    i.notas_ejecucion,
    i.problemas_encontrados,
    i.soluciones_aplicadas,
    i.calificacion_cliente,
    i.comentario_cliente,
    i.created_at,
    i.updated_at,
    c.nombre AS cliente_nombre,
    c.nombre_fantasia AS cliente_nombre_fantasia,
    e.modelo AS equipo_modelo,
    e.marca AS equipo_marca,
    te.nombre AS tipo_equipo_nombre,
    ul.nombre AS ubicacion_tipo_nombre,
    ( SELECT count(*) AS count
           FROM public.instalaciones_items
          WHERE (instalaciones_items.instalacion_id = i.id)) AS total_items,
    ( SELECT count(*) AS count
           FROM public.instalaciones_items
          WHERE ((instalaciones_items.instalacion_id = i.id) AND (instalaciones_items.estado_reserva = 'reservado'::text))) AS items_reservados,
    ( SELECT count(*) AS count
           FROM public.instalaciones_items
          WHERE ((instalaciones_items.instalacion_id = i.id) AND (instalaciones_items.estado_reserva = 'utilizado'::text))) AS items_utilizados,
    ( SELECT count(*) AS count
           FROM public.instalaciones_fotos
          WHERE (instalaciones_fotos.instalacion_id = i.id)) AS total_fotos,
    ( SELECT count(*) AS count
           FROM public.comentarios
          WHERE ((comentarios.entidad_tipo = 'instalacion'::text) AND (comentarios.entidad_id = i.id))) AS total_comentarios
   FROM ((((public.instalaciones i
     LEFT JOIN public.clientes c ON ((i.cliente_id = c.id)))
     LEFT JOIN public.equipos e ON ((i.equipo_id = e.id)))
     LEFT JOIN public.tipos_equipos te ON ((i.tipo_equipo_id = te.id)))
     LEFT JOIN public.ubicacion_personas ul ON ((i.ubicacion_tipo_id = ul.id)));


--
-- Name: VIEW instalaciones_completas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.instalaciones_completas IS 'Vista completa de instalaciones con datos relacionados';


