--
-- Name: mv_cliente_clv; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_cliente_clv AS
 SELECT c.id AS cliente_id,
    c.org_id,
    c.nombre AS cliente_nombre,
    (count(f.id))::integer AS total_facturas,
    COALESCE(sum(f.total), (0)::numeric) AS facturacion_total,
    min(f.fecha_emision) AS primera_compra,
    max(f.fecha_emision) AS ultima_compra,
        CASE
            WHEN (count(f.id) > 0) THEN (COALESCE(max(f.fecha_emision), CURRENT_DATE) - COALESCE(min(f.fecha_emision), CURRENT_DATE))
            ELSE 0
        END AS dias_como_cliente,
        CASE
            WHEN ((count(f.id) > 0) AND (min(f.fecha_emision) <> max(f.fecha_emision))) THEN (COALESCE(sum(f.total), (0)::numeric) / GREATEST((EXTRACT(epoch FROM age((max(f.fecha_emision))::timestamp with time zone, (min(f.fecha_emision))::timestamp with time zone)) / (30.0 * (86400)::numeric)), (1)::numeric))
            ELSE COALESCE(sum(f.total), (0)::numeric)
        END AS ingreso_mensual_promedio,
        CASE
            WHEN (count(f.id) >= 2) THEN (((max(f.fecha_emision) - min(f.fecha_emision)))::numeric / (GREATEST((count(f.id) - 1), (1)::bigint))::numeric)
            ELSE NULL::numeric
        END AS dias_entre_compras
   FROM (public.clientes c
     LEFT JOIN public.facturas f ON (((f.cliente_id = c.id) AND (f.org_id = c.org_id) AND (COALESCE(f.estado, ''::text) <> 'anulada'::text))))
  WHERE ((COALESCE(c.tipo_entidad, 'cliente'::character varying))::text <> 'proveedor'::text)
  GROUP BY c.id, c.org_id, c.nombre
  WITH NO DATA;


--
-- Name: mv_customer_insights; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_customer_insights AS
 SELECT c.id AS cliente_id,
    c.nombre,
    c.nombre_fantasia,
    c.factor_precio,
    c.score,
    c.estado,
    c.created_at AS cliente_desde,
    COALESCE(f.total_facturado, (0)::numeric) AS total_facturado,
    COALESCE(f.total_facturas, (0)::bigint) AS total_facturas,
    COALESCE(f.promedio_factura, (0)::numeric) AS promedio_factura,
    f.ultima_factura,
    c.saldo_a_favor AS saldo_acreedor,
    COALESCE(s.total_servicios, (0)::bigint) AS total_servicios,
    s.ultimo_servicio,
    COALESCE(e.equipos_en_comodato, (0)::bigint) AS equipos_en_comodato,
    GREATEST(COALESCE(f.ultima_factura, '1900-01-01'::date), COALESCE(s.ultimo_servicio, '1900-01-01'::date)) AS ultima_interaccion
   FROM (((public.clientes c
     LEFT JOIN LATERAL ( SELECT sum(facturas.total) AS total_facturado,
            count(*) AS total_facturas,
            avg(facturas.total) AS promedio_factura,
            max(facturas.fecha_emision) AS ultima_factura
           FROM public.facturas
          WHERE (facturas.cliente_id = c.id)) f ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS total_servicios,
            (max(equipos_servicios_tecnicos.fecha_solicitud))::date AS ultimo_servicio
           FROM public.equipos_servicios_tecnicos
          WHERE (equipos_servicios_tecnicos.cliente_id = c.id)) s ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS equipos_en_comodato
           FROM public.equipos_contratos
          WHERE ((equipos_contratos.cliente_id = c.id) AND (equipos_contratos.estado = 'activo'::text))) e ON (true))
  WITH NO DATA;


