    oportunidad_id uuid NOT NULL,
    tipo character varying(50) NOT NULL,
    titulo character varying(255),
    descripcion text,
    metadata jsonb DEFAULT '{}'::jsonb,
    usuario_id uuid,
    usuario_nombre character varying(255),
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT oportunidades_actividades_tipo_check CHECK (((tipo)::text = ANY ((ARRAY['nota'::character varying, 'llamada'::character varying, 'email'::character varying, 'reunion'::character varying, 'tarea'::character varying, 'archivo'::character varying, 'etapa_cambio'::character varying, 'presupuesto_creado'::character varying, 'presupuesto_enviado'::character varying, 'ganada'::character varying, 'perdida'::character varying])::text[])))
);


--
-- Name: TABLE oportunidades_actividades; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.oportunidades_actividades IS 'Registro de actividades en oportunidades de venta (CRM timeline)';


--
-- Name: COLUMN oportunidades_actividades.tipo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.oportunidades_actividades.tipo IS 'Tipo de actividad: nota, llamada, email, reunion, tarea, etapa_cambio, presupuesto_creado, presupuesto_enviado, ganada, perdida';


--
-- Name: COLUMN oportunidades_actividades.metadata; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.oportunidades_actividades.metadata IS 'Datos específicos según tipo: {destinatario, asunto} para email, {etapa_anterior, etapa_nueva} para cambio etapa, etc.';


