    oportunidad_item_id uuid,
    equipo_id uuid NOT NULL,
    cantidad integer DEFAULT 1 NOT NULL,
    especificaciones text,
    estado character varying(30) DEFAULT 'pendiente'::character varying NOT NULL,
    orden_compra_id uuid,
    proveedor_id uuid,
    fecha_solicitud date,
    fecha_estimada_llegada date,
    fecha_recepcion date,
    equipo_unidad_id uuid,
    notas text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    created_by uuid,
    CONSTRAINT oportunidades_equipos_pedidos_estado_check CHECK (((estado)::text = ANY (ARRAY[('pendiente'::character varying)::text, ('solicitado'::character varying)::text, ('en_transito'::character varying)::text, ('recibido'::character varying)::text, ('asignado'::character varying)::text, ('cancelado'::character varying)::text])))
);


