-- Name: TABLE oportunidades_equipos_pedidos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.oportunidades_equipos_pedidos IS 'Seguimiento de equipos nuevos a comprar para oportunidades de venta';


