    estado_item character varying(30) DEFAULT 'cotizado'::character varying,
    notas text,
    fecha_reserva timestamp with time zone,
    CONSTRAINT oportunidades_items_estado_item_check CHECK (((estado_item)::text = ANY (ARRAY[('cotizado'::character varying)::text, ('reservado'::character varying)::text, ('pedido_compra'::character varying)::text, ('recibido'::character varying)::text, ('entregado'::character varying)::text, ('cancelado'::character varying)::text])))
);


