COMMENT ON COLUMN public.oportunidades_items.equipo_unidad_id IS 'Unidad específica de equipo reservada (para equipos usados/en stock)';


--
-- Name: COLUMN oportunidades_items.estado_item; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.oportunidades_items.estado_item IS 'Estado del item: cotizado, reservado (stock), pedido_compra (nuevo), recibido, entregado';


--
-- Name: oportunidades_venta; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.oportunidades_venta (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    nombre character varying(255) NOT NULL,
    descripcion text,
    cliente_id uuid,
    contacto_nombre character varying(255),
    contacto_telefono character varying(50),
    contacto_email character varying(255),
    monto_estimado numeric(12,2),
    probabilidad_cierre integer,
    monto_ponderado numeric(12,2) GENERATED ALWAYS AS (((monto_estimado * (probabilidad_cierre)::numeric) / (100)::numeric)) STORED,
    etapa character varying(50) DEFAULT 'lead'::character varying NOT NULL,
    fecha_estimada_cierre date,
    fecha_primer_contacto date,
    fecha_ultimo_contacto date,
    dias_en_etapa integer DEFAULT 0,
    presupuesto_id uuid,
    pedido_id uuid,
    factura_id uuid,
    usuario_asignado_id uuid,
    fuente character varying(100),
    motivo_perdida text,
    competidor character varying(255),
    estado character varying(50) DEFAULT 'abierto'::character varying,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    etiquetas text[] DEFAULT '{}'::text[],
    prioridad character varying(20) DEFAULT 'normal'::character varying,
    empresa_nombre character varying(255),
    vendedor_id uuid,
    moneda character varying(3) DEFAULT 'ARS'::character varying,
    persona_id uuid,
    org_id uuid NOT NULL,
    perdida_descripcion text,
    creado_por uuid,
    laboratorio_id uuid,
    CONSTRAINT oportunidades_venta_prioridad_check CHECK (((prioridad)::text = ANY (ARRAY[('baja'::character varying)::text, ('normal'::character varying)::text, ('alta'::character varying)::text, ('urgente'::character varying)::text]))),
    CONSTRAINT oportunidades_venta_probabilidad_cierre_check CHECK (((probabilidad_cierre >= 0) AND (probabilidad_cierre <= 100)))
);


--
-- Name: TABLE oportunidades_venta; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.oportunidades_venta IS 'Pipeline de ventas - CRM';


--
-- Name: COLUMN oportunidades_venta.etiquetas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.oportunidades_venta.etiquetas IS 'Etiquetas/tags para categorizar (ej: veterinaria equipos, bioquimica, licitación)';


--
-- Name: COLUMN oportunidades_venta.prioridad; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.oportunidades_venta.prioridad IS 'Nivel de prioridad: baja, normal, alta, urgente';


--
