--
-- Name: org_contacts_with_persona; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.org_contacts_with_persona AS
 SELECT oc.id,
    oc.org_id,
    oc.persona_id,
    oc.tipo,
    oc.datos_extra,
    oc.credito_limite,
    oc.created_at,
    p.nombre AS persona_nombre,
    p.email AS persona_email,
    p.telefono AS persona_telefono,
    p.documento_tipo,
    p.documento_nro
   FROM (public.org_contacts oc
     JOIN public.personas p ON ((p.id = oc.persona_id)));


