    mp_live_mode boolean,
    mp_raw jsonb,
    org_id uuid,
    CONSTRAINT ren_pagos_estado_check CHECK ((estado = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'cancelled'::text, 'refunded'::text]))),
    CONSTRAINT ren_pagos_metodo_check CHECK ((metodo = ANY (ARRAY['mercadopago'::text, 'transferencia'::text, 'efectivo'::text])))
);


