--
-- Name: presupuestos_con_lista; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.presupuestos_con_lista AS
 SELECT p.id,
    p.numero,
    p.cliente_id,
    p.fecha_emision,
    p.fecha_vencimiento,
    p.estado,
    p.subtotal,
    p.descuento,
    p.iva,
    p.total,
    p.observaciones,
    p.terminos_condiciones,
    p.tiempo_entrega,
    p.forma_pago,
    p.created_at,
    p.updated_at,
    p.plantilla_id,
    p.oportunidad_id,
    p.usuario_vendedor_id,
    p.fecha_envio,
    p.fecha_visto,
    p.fecha_respuesta,
    p.convertido_pedido,
    p.pedido_id,
    p.motivo_rechazo,
    p.competidor_perdido,
    p.margen_total,
    p.costo_total,
    p.validez_dias,
    p.condiciones_pago,
    p.notas,
    p.token_firma,
    p.titulo,
    p.firmado,
    p.fecha_firma,
    p.firma_nombre,
    p.firma_ip,
    p.firma_imagen,
    p.lista_precios_id,
    p.moneda,
    p.cotizacion_usd,
    p.mostrar_en_usd,
    p.tipo_cotizacion,
    lp.nombre AS lista_precios_nombre,
    lp.codigo AS lista_precios_codigo,
    lp.margen_porcentaje AS lista_precios_margen
   FROM (public.presupuestos p
     LEFT JOIN public.listas_precios lp ON ((p.lista_precios_id = lp.id)));


--
-- Name: VIEW presupuestos_con_lista; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.presupuestos_con_lista IS 'Presupuestos con información de lista de precios';


