    "tieneLote" boolean DEFAULT false,
    stock_actual numeric(10,2) DEFAULT 0,
    stock_minimo numeric(10,2) DEFAULT 0,
    stock_maximo numeric(10,2),
    precio_unitario numeric(15,2),
    ubicacion text,
    lote text,
    fecha_vencimiento date,
    fabricante text,
    temperatura_almacenamiento text,
    precio_costo numeric(15,2) DEFAULT 0,
    precio_venta numeric(15,2) DEFAULT 0,
    proveedor_habitual_id uuid,
    ultima_compra_fecha date,
    ultima_compra_precio numeric(15,2),
    moneda character varying(3) DEFAULT 'ARS'::character varying,
    imagen_url text,
    margen_pesos numeric(15,2) GENERATED ALWAYS AS ((precio_venta - precio_costo)) STORED,
    nombre_comercial text,
    org_id uuid NOT NULL,
    descripcion text,
    descripcion_corta text,
    slug text,
    imagenes text[] DEFAULT '{}'::text[],
    deleted_at timestamp with time zone,
    categoria_id uuid,
    marca_id uuid,
    cepa_id uuid,
    banco_semillas_id uuid,
    margen_porcentaje numeric(10,2) GENERATED ALWAYS AS (
CASE
    WHEN ((precio_venta > (0)::numeric) AND (precio_costo > (0)::numeric)) THEN (((precio_venta - precio_costo) / precio_venta) * (100)::numeric)
    ELSE (0)::numeric
END) STORED,
    deposito_id uuid,
    es_recurrente boolean DEFAULT false NOT NULL
);


--
-- Name: COLUMN productos.stock_actual; Type: COMMENT; Schema: public; Owner: -
