--
-- Name: productos_completos; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.productos_completos AS
 SELECT p.id,
    p.nombre,
    p.codigo,
    p.categoria,
    p.unidad_medida,
    p.proveedor_id,
    p.created_at,
    p."tieneLote",
    p.stock_actual,
    p.stock_minimo,
    p.stock_maximo,
    p.precio_unitario,
    p.ubicacion,
    p.lote,
    p.fecha_vencimiento,
    p.fabricante,
    p.temperatura_almacenamiento,
    p.precio_costo,
    p.precio_venta,
    p.proveedor_habitual_id,
    p.ultima_compra_fecha,
    p.ultima_compra_precio,
    p.moneda,
    p.imagen_url,
    p.margen_pesos,
    p.nombre_comercial,
    p.org_id,
    p.descripcion,
    p.descripcion_corta,
    p.slug,
    p.imagenes,
    p.deleted_at,
    p.categoria_id,
    p.marca_id,
    p.cepa_id,
    p.banco_semillas_id,
    p.margen_porcentaje,
    pw.precio_oferta,
    pw.caracteristicas,
    pw.peso_gramos,
    pw.dimensiones,
    pw.destacado,
    COALESCE(c.nombre, p.categoria) AS categoria_nombre,
    c.slug AS categoria_slug,
    c.imagen_url AS categoria_imagen,
    COALESCE(m.nombre, p.fabricante) AS marca_nombre,
    m.slug AS marca_slug,
    m.logo_url AS marca_logo
   FROM (((public.productos p
     LEFT JOIN public.productos_web pw ON ((pw.producto_id = p.id)))
     LEFT JOIN public.categorias c ON ((c.id = p.categoria_id)))
     LEFT JOIN public.marcas m ON ((m.id = p.marca_id)))
  WHERE (p.deleted_at IS NULL);


