--
-- Name: proveedor_historial_precios; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.proveedor_historial_precios (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    proveedor_id uuid NOT NULL,
    producto_id uuid,
    lista_id uuid,
    precio_anterior numeric(15,4),
    precio_nuevo numeric(15,4) NOT NULL,
    moneda character varying(3) DEFAULT 'ARS'::character varying NOT NULL,
    variacion_porcentaje numeric(8,2) GENERATED ALWAYS AS (
CASE
    WHEN (precio_anterior > (0)::numeric) THEN (((precio_nuevo - precio_anterior) / precio_anterior) * (100)::numeric)
    ELSE NULL::numeric
END) STORED,
    motivo character varying(50),
    notas text,
    fecha_cambio timestamp with time zone DEFAULT now(),
    created_by uuid
);


