    cantidad_minima numeric(10,2) DEFAULT 1,
    descuento_porcentaje numeric(5,2) DEFAULT 0,
    precio_neto numeric(15,4) GENERATED ALWAYS AS ((precio_costo * ((1)::numeric - (COALESCE(descuento_porcentaje, (0)::numeric) / (100)::numeric)))) STORED,
    plazo_entrega_dias integer,
    unidad_medida character varying(20),
    factor_conversion numeric(10,4) DEFAULT 1,
    activo boolean DEFAULT true,
    fila_origen integer,
