    comunicado_por uuid,
    comunicado_medio text,
    contacto_telefono text,
    contacto_email text,
    CONSTRAINT chk_servicios_sin_cargo_motivo CHECK (((NOT sin_cargo) OR ((motivo_sin_cargo IS NOT NULL) AND (motivo_sin_cargo <> ''::text))))
);


