);


--
-- Name: servicios_completos; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.servicios_completos AS
 SELECT s.id,
    s.equipo_id,
    s.cliente_id,
    s.tipo,
    s.descripcion,
    s.estado,
    s.fecha,
    s.fecha_fin,
    s.analiticas,
    s.comentarios,
    s.created_at,
    s.tecnico,
    s.tipo_servicio,
    s.diagnostico,
    s.detalle_privado,
    s.insumos_utilizados,
    s.contacto,
    s.falla_declarada,
    s.modo_de_contacto,
    s.garantia,
    s.tipo_garantia,
    s.accesorios_entrantes,
    s.facturado,
    s.factura_link,
    s.estado_contable,
    s.tipo_service,
    s.monto_servicio,
    s.monto_insumos,
    s.updated_at,
    c.nombre AS cliente_nombre,
    c.cuit AS cliente_cuit,
    c.email AS cliente_email,
    c.telefono AS cliente_telefono,
    eq.modelo AS equipo_modelo,
    eq.marca AS equipo_marca,
    eq.tipo AS equipo_tipo
   FROM (((public.servicios s
     LEFT JOIN public.clientes c ON ((s.cliente_id = c.id)))
     LEFT JOIN public.equipos_unidades eu ON ((s.equipo_id = eu.id)))
     LEFT JOIN public.equipos eq ON ((eu.equipo_id = eq.id)));


