    CONSTRAINT tareas_estado_check CHECK (((estado)::text = ANY (ARRAY[('pendiente'::character varying)::text, ('asignada'::character varying)::text, ('en_proceso'::character varying)::text, ('en_espera'::character varying)::text, ('completada'::character varying)::text, ('cancelada'::character varying)::text]))),
    CONSTRAINT tareas_prioridad_check CHECK (((prioridad)::text = ANY (ARRAY[('baja'::character varying)::text, ('media'::character varying)::text, ('alta'::character varying)::text, ('urgente'::character varying)::text]))),
    CONSTRAINT tareas_tipo_check CHECK (((tipo)::text = ANY (ARRAY[('servicio_tecnico'::character varying)::text, ('instalacion'::character varying)::text, ('reparacion'::character varying)::text, ('mantenimiento'::character varying)::text, ('consulta_tecnica'::character varying)::text, ('presupuesto'::character varying)::text, ('seguimiento_comercial'::character varying)::text, ('reclamo'::character varying)::text, ('otro'::character varying)::text])))
);


