--
-- Name: v_cliente_laboratorios; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_cliente_laboratorios AS
 SELECT id AS cliente_id,
    org_id,
    nombre AS cliente_nombre,
    cuit AS cliente_cuit,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('laboratorio_id', lrs.laboratorio_id, 'nombre', l.nombre, 'codigo', l.codigo, 'localidad', l.localidad, 'es_principal', lrs.es_principal, 'ambito', lrs.ambito) ORDER BY lrs.es_principal DESC, l.nombre) AS jsonb_agg
           FROM (public.laboratorio_razones_sociales lrs
             JOIN public.laboratorios l ON ((l.id = lrs.laboratorio_id)))
          WHERE ((lrs.cliente_id = c.id) AND (lrs.activo = true))), '[]'::jsonb) AS laboratorios
   FROM public.clientes c
  WHERE ((tipo_entidad)::text = 'cliente'::text);


--
-- Name: v_cobros_con_aplicaciones; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_cobros_con_aplicaciones AS
 SELECT id,
    nro_pago,
    monto,
    fecha_pago,
    metodo_pago,
    notas,
    cliente_id,
    factura_id AS factura_principal_id,
    COALESCE(( SELECT json_agg(json_build_object('factura_id', ca.factura_id, 'monto_aplicado', ca.monto_aplicado, 'nro_factura', f.nro_factura, 'tipo_factura', f.tipo_factura, 'total_factura', f.total) ORDER BY f.nro_factura) AS json_agg
           FROM (public.cobros_aplicaciones ca
             JOIN public.facturas f ON ((ca.factura_id = f.id)))
          WHERE (ca.cobro_id = c.id)), '[]'::json) AS aplicaciones,
    COALESCE(( SELECT sum(ca.monto_aplicado) AS sum
           FROM public.cobros_aplicaciones ca
          WHERE (ca.cobro_id = c.id)), (0)::numeric) AS total_aplicado,
    (monto - COALESCE(( SELECT sum(ca.monto_aplicado) AS sum
           FROM public.cobros_aplicaciones ca
          WHERE (ca.cobro_id = c.id)), (0)::numeric)) AS saldo_sin_aplicar
   FROM public.cobros c;


--
-- Name: v_comparacion_precios_proveedores; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_comparacion_precios_proveedores AS
 SELECT p.id AS producto_id,
    p.codigo AS producto_codigo,
    p.nombre AS producto_nombre,
    prov.id AS proveedor_id,
    prov.nombre AS proveedor_nombre,
    plp.nombre AS lista_nombre,
    plp.moneda,
    pli.codigo_proveedor,
    pli.precio_costo,
    pli.descuento_porcentaje,
    pli.precio_neto,
    pli.cantidad_minima,
    COALESCE(pli.plazo_entrega_dias, plp.plazo_entrega_dias) AS plazo_entrega_dias,
    plp.fecha_inicio,
    plp.fecha_fin,
    plp.estado AS lista_estado
   FROM (((public.proveedor_lista_items pli
     JOIN public.proveedor_listas_precios plp ON ((plp.id = pli.lista_id)))
     JOIN public.proveedores prov ON ((prov.id = plp.proveedor_id)))
     JOIN public.productos p ON ((p.id = pli.producto_id)))
  WHERE (pli.activo = true)
  ORDER BY p.codigo, pli.precio_neto;


--
-- Name: v_equipos_disponibles_reserva; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_equipos_disponibles_reserva AS
 SELECT eu.id AS unidad_id,
    eu.numero_serie,
    eu.codigo,
    eu.estado_general,
    eu.fecha_compra,
    e.id AS equipo_id,
    e.marca,
    e.modelo,
    e.tipo,
    e.categoria,
    e.condicion,
    e.precio_lista,
    e.precio_lista_moneda,
    e.imagen_url
   FROM (public.equipos_unidades eu
     JOIN public.equipos e ON ((eu.equipo_id = e.id)))
  WHERE ((eu.estado_general = 'stock'::text) AND (eu.activo = true) AND (eu.oportunidad_reserva_id IS NULL));


--
-- Name: VIEW v_equipos_disponibles_reserva; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_equipos_disponibles_reserva IS 'Equipos en stock disponibles para reservar en oportunidades';


--
-- Name: v_equipos_pendientes_compra; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_equipos_pendientes_compra AS
 SELECT oep.id,
    oep.oportunidad_id,
    oep.oportunidad_item_id,
    oep.equipo_id,
    oep.cantidad,
    oep.especificaciones,
    oep.estado,
    oep.orden_compra_id,
    oep.proveedor_id,
    oep.fecha_solicitud,
    oep.fecha_estimada_llegada,
    oep.fecha_recepcion,
    oep.equipo_unidad_id,
    oep.notas,
    oep.created_at,
    oep.updated_at,
    oep.created_by,
    e.marca,
    e.modelo,
    e.tipo,
    e.categoria,
    o.nombre AS oportunidad_nombre,
    o.etapa AS oportunidad_etapa,
    o.estado AS oportunidad_estado,
    c.nombre AS cliente_nombre,
    p.nombre AS proveedor_nombre
   FROM ((((public.oportunidades_equipos_pedidos oep
     JOIN public.equipos e ON ((oep.equipo_id = e.id)))
     JOIN public.oportunidades_venta o ON ((oep.oportunidad_id = o.id)))
     LEFT JOIN public.clientes c ON ((o.cliente_id = c.id)))
     LEFT JOIN public.proveedores p ON ((oep.proveedor_id = p.id)))
  WHERE ((oep.estado)::text <> ALL (ARRAY[('recibido'::character varying)::text, ('asignado'::character varying)::text, ('cancelado'::character varying)::text]));


--
-- Name: VIEW v_equipos_pendientes_compra; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_equipos_pendientes_compra IS 'Equipos pendientes de comprar para oportunidades';


--
-- Name: v_equipos_ubicacion; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_equipos_ubicacion AS
 SELECT eu.id,
    eu.codigo,
    eu.numero_serie,
    eu.estado_general,
    eu.estado_comodato,
    eu.activo,
    e.id AS equipo_catalogo_id,
    e.tipo AS tipo_equipo,
    e.marca,
    e.modelo,
    eu.laboratorio_id,
    l.nombre AS laboratorio_nombre,
    l.direccion AS laboratorio_direccion,
    l.localidad AS laboratorio_localidad,
    l.provincia AS laboratorio_provincia,
    l.razon_social_id,
    c.nombre AS razon_social_nombre,
    c.cuit AS razon_social_cuit,
    eu.fecha_compra,
    eu.fecha_asignacion,
    eu.fecha_vencimiento_garantia,
    eu.ultimo_mantenimiento,
    eu.proximo_mantenimiento,
    eu.created_at,
    eu.updated_at
   FROM (((public.equipos_unidades eu
     JOIN public.equipos e ON ((e.id = eu.equipo_id)))
     LEFT JOIN public.laboratorios l ON ((l.id = eu.laboratorio_id)))
     LEFT JOIN public.clientes c ON ((c.id = l.razon_social_id)));


--
-- Name: VIEW v_equipos_ubicacion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_equipos_ubicacion IS 'Vista de equipos con su ubicación completa (laboratorio y razón social)';


--
-- Name: v_laboratorios_con_razones; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_laboratorios_con_razones AS
 SELECT l.id AS laboratorio_id,
    l.org_id,
    l.nombre AS laboratorio_nombre,
    l.codigo AS laboratorio_codigo,
    l.localidad,
    l.provincia,
    l.activo AS laboratorio_activo,
    lrs_principal.cliente_id AS razon_social_principal_id,
    c_principal.nombre AS razon_social_principal_nombre,
    c_principal.cuit AS razon_social_principal_cuit,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('cliente_id', lrs.cliente_id, 'nombre', c.nombre, 'cuit', c.cuit, 'es_principal', lrs.es_principal, 'ambito', lrs.ambito, 'notas', lrs.notas) ORDER BY lrs.es_principal DESC, c.nombre) AS jsonb_agg
           FROM (public.laboratorio_razones_sociales lrs
             JOIN public.clientes c ON ((c.id = lrs.cliente_id)))
          WHERE ((lrs.laboratorio_id = l.id) AND (lrs.activo = true))), '[]'::jsonb) AS razones_sociales
   FROM ((public.laboratorios l
     LEFT JOIN public.laboratorio_razones_sociales lrs_principal ON (((lrs_principal.laboratorio_id = l.id) AND (lrs_principal.es_principal = true) AND (lrs_principal.activo = true))))
     LEFT JOIN public.clientes c_principal ON ((c_principal.id = lrs_principal.cliente_id)));


--
-- Name: v_mejor_precio_producto; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_mejor_precio_producto AS
 WITH precios_vigentes AS (
         SELECT DISTINCT ON (pli.producto_id) pli.producto_id,
            plp.proveedor_id,
            prov.nombre AS proveedor_nombre,
            plp.id AS lista_id,
            plp.nombre AS lista_nombre,
            pli.precio_costo,
            pli.precio_neto,
            plp.moneda,
            pli.cantidad_minima,
            pli.plazo_entrega_dias,
            plp.fecha_inicio,
            plp.fecha_fin
           FROM ((public.proveedor_lista_items pli
             JOIN public.proveedor_listas_precios plp ON ((plp.id = pli.lista_id)))
             JOIN public.proveedores prov ON ((prov.id = plp.proveedor_id)))
          WHERE (((plp.estado)::text = 'activa'::text) AND (pli.activo = true) AND (plp.fecha_inicio <= CURRENT_DATE) AND ((plp.fecha_fin IS NULL) OR (plp.fecha_fin >= CURRENT_DATE)))
          ORDER BY pli.producto_id, pli.precio_neto
        )
 SELECT p.id AS producto_id,
    p.codigo,
    p.nombre,
    pv.proveedor_id,
    pv.proveedor_nombre,
    pv.precio_neto AS mejor_precio,
    pv.moneda,
    pv.cantidad_minima,
    pv.plazo_entrega_dias,
    p.precio_costo AS precio_actual,
        CASE
            WHEN (p.precio_costo > (0)::numeric) THEN (((pv.precio_neto - p.precio_costo) / p.precio_costo) * (100)::numeric)
            ELSE NULL::numeric
        END AS diferencia_porcentaje
   FROM (public.productos p
     LEFT JOIN precios_vigentes pv ON ((pv.producto_id = p.id)));


--
-- Name: v_operaciones_sin_cargo; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_operaciones_sin_cargo AS
 SELECT 'pedido'::text AS tipo,
    p.id,
    p.org_id,
    p.cliente_id,
    p.numero AS numero_operacion,
    p.motivo_sin_cargo,
    p.created_at AS fecha,
    ( SELECT COALESCE(sum((pi.precio_unitario * pi.cantidad)), (0)::numeric) AS "coalesce"
           FROM public.pedidos_items pi
          WHERE ((pi.pedido_id = p.id) AND (pi.sin_cargo = true))) AS monto_equivalente
   FROM public.pedidos p
  WHERE (p.sin_cargo = true)
UNION ALL
 SELECT 'servicio'::text AS tipo,
    s.id,
    s.org_id,
    s.cliente_id,
    NULL::text AS numero_operacion,
    s.motivo_sin_cargo,
    s.created_at AS fecha,
    (COALESCE(s.monto_servicio, (0)::numeric) + COALESCE(s.monto_insumos, (0)::numeric)) AS monto_equivalente
   FROM public.servicios s
  WHERE (s.sin_cargo = true);


--
-- Name: v_retenciones_pendientes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_retenciones_pendientes AS
 SELECT r.id,
    r.pago_id,
    r.cobro_id,
    r.factura_id,
    r.cliente_id,
    r.tipo,
    r.jurisdiccion,
    r.base_imponible,
    r.alicuota,
    r.monto,
    r.numero_certificado,
    r.fecha_retencion,
    r.regimen_codigo,
    r.regimen_descripcion,
    r.periodo_fiscal,
    r.declarado,
    r.fecha_declaracion,
    r.notas,
    r.archivo_certificado_url,
    r.created_at,
    r.updated_at,
    r.created_by,
    c.nombre AS cliente_nombre,
    c.cuit AS cliente_cuit,
    f.nro_factura,
    f.total AS factura_total
   FROM ((public.retenciones r
     LEFT JOIN public.clientes c ON ((r.cliente_id = c.id)))
     LEFT JOIN public.facturas f ON ((r.factura_id = f.id)))
  WHERE (r.declarado = false)
  ORDER BY r.fecha_retencion DESC;


--
-- Name: v_retenciones_resumen; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_retenciones_resumen AS
 SELECT periodo_fiscal,
    tipo,
    jurisdiccion,
    count(*) AS cantidad,
    sum(base_imponible) AS total_base_imponible,
    sum(monto) AS total_retenido,
    sum(
        CASE
            WHEN declarado THEN monto
            ELSE (0)::numeric
        END) AS total_declarado,
    sum(
        CASE
            WHEN (NOT declarado) THEN monto
            ELSE (0)::numeric
        END) AS total_pendiente
   FROM public.retenciones
  GROUP BY periodo_fiscal, tipo, jurisdiccion
  ORDER BY periodo_fiscal DESC, tipo, jurisdiccion;


