    descripcion text NOT NULL,
    cantidad numeric(10,2) DEFAULT 1 NOT NULL,
    precio_unitario numeric(12,2) DEFAULT 0 NOT NULL,
    descuento_pct numeric(5,2) DEFAULT 0,
    sin_cargo boolean DEFAULT false,
    subtotal numeric(12,2) GENERATED ALWAYS AS (
CASE
    WHEN sin_cargo THEN (0)::numeric
    ELSE ((cantidad * precio_unitario) * ((1)::numeric - (COALESCE(descuento_pct, (0)::numeric) / (100)::numeric)))
END) STORED,
    origen_precio text DEFAULT 'catalogo'::text,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT vet_cuenta_items_origen_precio_check CHECK ((origen_precio = ANY (ARRAY['cliente'::text, 'catalogo'::text, 'manual'::text]))),
    CONSTRAINT vet_cuenta_items_tipo_check CHECK ((tipo = ANY (ARRAY['consulta'::text, 'vacunacion'::text, 'desparasitacion'::text, 'cirugia'::text, 'estudio'::text, 'internacion_dia'::text, 'grooming'::text, 'medicamento'::text, 'servicio'::text])))
);


