--
-- Name: vet_ordenes_detalle; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vet_ordenes_detalle AS
 SELECT o.id,
    o.org_id,
    o.numero_orden,
    o.paciente_id,
    o.cliente_id,
    o.veterinario_solicitante,
    o.fecha_orden,
    o.fecha_estimada_resultado,
    o.estado,
    o.prioridad,
    o.observaciones,
    o.subtotal,
    o.total,
    o.protocolo,
    o.deleted_at,
    o.created_at,
    o.updated_at,
    pac.nombre AS paciente_nombre,
    pac.especie AS paciente_especie,
    per.nombre AS cliente_nombre,
    per.email AS cliente_email,
    ( SELECT count(*) AS count
           FROM public.vet_orden_estudios oe
          WHERE ((oe.orden_id = o.id) AND (oe.deleted_at IS NULL))) AS total_estudios,
    ( SELECT count(*) AS count
           FROM public.vet_orden_estudios oe
          WHERE ((oe.orden_id = o.id) AND (oe.estado = 'completado'::text) AND (oe.deleted_at IS NULL))) AS estudios_completados
   FROM ((public.vet_ordenes_trabajo o
     JOIN public.vet_pacientes pac ON ((pac.id = o.paciente_id)))
     JOIN public.personas per ON ((per.id = o.cliente_id)))
  WHERE (o.deleted_at IS NULL);


--
-- Name: vet_ordenes_trabajo_numero_orden_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.vet_ordenes_trabajo_numero_orden_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: vet_ordenes_trabajo_numero_orden_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.vet_ordenes_trabajo_numero_orden_seq OWNED BY public.vet_ordenes_trabajo.numero_orden;


--
