CREATE VIEW public.vet_pacientes_con_cliente AS
 SELECT p.id,
    p.org_id,
    p.cliente_id,
    p.nombre,
    p.especie,
    p.raza,
    p.sexo,
    p.fecha_nacimiento,
    p.peso,
    p.color,
    p.numero_chip,
    p.observaciones,
    p.activo,
    p.deleted_at,
    p.created_at,
    p.updated_at,
    per.nombre AS cliente_nombre,
    per.email AS cliente_email,
    per.telefono AS cliente_telefono
   FROM (public.vet_pacientes p
     JOIN public.personas per ON ((per.id = p.cliente_id)))
  WHERE (p.deleted_at IS NULL);


