--
-- Name: vet_reactivos_stock_bajo; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vet_reactivos_stock_bajo AS
 SELECT r.id,
    r.org_id,
    r.nombre,
    r.codigo,
    r.categoria,
    r.marca,
    r.proveedor_id,
    r.numero_lote,
    r.fecha_vencimiento,
    r.cantidad_actual,
    r.cantidad_minima,
    r.cantidad_maxima,
    r.unidad_medida,
    r.precio_unitario,
    r.ubicacion,
    r.temperatura_almacenamiento,
    r.estudios_asociados,
    r.consumo_por_prueba,
    r.activo,
    r.deleted_at,
    r.created_at,
    r.updated_at,
    prov.nombre AS proveedor_nombre
   FROM (public.vet_reactivos r
     LEFT JOIN public.vet_proveedores prov ON ((prov.id = r.proveedor_id)))
  WHERE ((r.activo = true) AND (r.deleted_at IS NULL) AND (r.cantidad_minima IS NOT NULL) AND (r.cantidad_actual < r.cantidad_minima));


