--
-- Name: vet_seguimientos_pendientes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vet_seguimientos_pendientes AS
 SELECT s.id,
    s.org_id,
    s.paciente_id,
    s.programa_bienestar_id,
    s.fecha_programada,
    s.fecha_completado,
    s.estado,
    s.tipo,
    s.motivo,
    s.estudios_incluidos,
    s.observaciones,
    s.created_by,
    s.deleted_at,
    s.created_at,
    s.updated_at,
    pac.nombre AS paciente_nombre,
    pac.especie AS paciente_especie,
    per.nombre AS cliente_nombre,
    per.email AS cliente_email,
    per.telefono AS cliente_telefono
   FROM ((public.vet_seguimientos s
     JOIN public.vet_pacientes pac ON ((pac.id = s.paciente_id)))
     JOIN public.personas per ON ((per.id = pac.cliente_id)))
  WHERE ((s.estado = ANY (ARRAY['pendiente'::text, 'notificado'::text])) AND (s.deleted_at IS NULL) AND (s.fecha_programada <= (CURRENT_DATE + '7 days'::interval)));


