CREATE TABLE public.vision_logs (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    org_id uuid NOT NULL,
    user_id uuid,
    domain text NOT NULL,
    task_type text NOT NULL,
    model text NOT NULL,
    image_count integer DEFAULT 1 NOT NULL,
    prompt_tokens integer DEFAULT 0 NOT NULL,
    completion_tokens integer DEFAULT 0 NOT NULL,
    estimated_cost_usd numeric(10,6) DEFAULT 0 NOT NULL,
    duration_ms integer DEFAULT 0 NOT NULL,
    success boolean DEFAULT true NOT NULL,
    error text,
    prompt_summary text,
    result_summary text,
    entity_type text,
    entity_id uuid,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT vision_logs_task_type_check CHECK ((task_type = ANY (ARRAY['extraction'::text, 'analysis'::text, 'classification'::text])))
);


--
-- Name: vista_cuentas_corrientes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vista_cuentas_corrientes AS
 SELECT c.id AS cliente_id,
    c.org_id,
    c.nombre,
    c.nombre_fantasia,
    c.cuit,
    c.estado,
    (c.email)::text AS email,
    (c.telefono)::text AS telefono,
    COALESCE(sum(
        CASE
            WHEN (f.tipo_factura <> 'IVR'::text) THEN f.total
            ELSE (0)::numeric
        END), (0)::numeric) AS total_facturado_legal,
    count(
        CASE
            WHEN (f.tipo_factura <> 'IVR'::text) THEN f.id
            ELSE NULL::uuid
        END) AS cantidad_facturas_legal,
    COALESCE(sum(
        CASE
            WHEN (f.tipo_factura = 'IVR'::text) THEN f.total
            ELSE (0)::numeric
        END), (0)::numeric) AS total_remitido_ivr,
    count(
        CASE
            WHEN (f.tipo_factura = 'IVR'::text) THEN f.id
            ELSE NULL::uuid
        END) AS cantidad_ivr,
    COALESCE(( SELECT sum(p.monto) AS sum
           FROM (public.pagos p
             JOIN public.facturas fp ON ((p.factura_id = fp.id)))
          WHERE ((fp.cliente_id = c.id) AND (fp.tipo_factura <> 'IVR'::text))), (0)::numeric) AS total_pagado_legal,
    COALESCE(( SELECT sum(cb.monto) AS sum
           FROM (public.cobros cb
             JOIN public.facturas fi ON ((cb.factura_id = fi.id)))
          WHERE ((fi.cliente_id = c.id) AND (fi.tipo_factura = 'IVR'::text))), (0)::numeric) AS total_cobrado_ivr,
    COALESCE(( SELECT sum(nc.monto) AS sum
           FROM (public.notas_credito nc
             JOIN public.facturas fn ON ((nc.factura_id = fn.id)))
          WHERE ((fn.cliente_id = c.id) AND (fn.tipo_factura <> 'IVR'::text))), (0)::numeric) AS total_notas_credito,
    ((COALESCE(sum(
        CASE
            WHEN (f.tipo_factura <> 'IVR'::text) THEN f.total
            ELSE (0)::numeric
        END), (0)::numeric) - COALESCE(( SELECT sum(p.monto) AS sum
           FROM (public.pagos p
             JOIN public.facturas fp ON ((p.factura_id = fp.id)))
          WHERE ((fp.cliente_id = c.id) AND (fp.tipo_factura <> 'IVR'::text))), (0)::numeric)) - COALESCE(( SELECT sum(nc.monto) AS sum
           FROM (public.notas_credito nc
             JOIN public.facturas fn ON ((nc.factura_id = fn.id)))
          WHERE ((fn.cliente_id = c.id) AND (fn.tipo_factura <> 'IVR'::text))), (0)::numeric)) AS saldo_legal,
    (COALESCE(sum(
        CASE
            WHEN (f.tipo_factura = 'IVR'::text) THEN f.total
            ELSE (0)::numeric
        END), (0)::numeric) - COALESCE(( SELECT sum(cb.monto) AS sum
           FROM (public.cobros cb
             JOIN public.facturas fi ON ((cb.factura_id = fi.id)))
          WHERE ((fi.cliente_id = c.id) AND (fi.tipo_factura = 'IVR'::text))), (0)::numeric)) AS saldo_ivr,
    COALESCE(c.saldo_a_favor, (0)::numeric) AS saldo_a_favor_legal,
    COALESCE(c.saldo_a_favor_ivr, (0)::numeric) AS saldo_a_favor_ivr,
    COALESCE(( SELECT sum((f2.total - COALESCE(( SELECT sum(p2.monto) AS sum
                   FROM public.pagos p2
                  WHERE (p2.factura_id = f2.id)), (0)::numeric))) AS sum
           FROM public.facturas f2
          WHERE ((f2.cliente_id = c.id) AND (f2.tipo_factura <> 'IVR'::text) AND (f2.estado <> ALL (ARRAY['pagada'::text, 'anulada'::text])) AND (f2.fecha_vencimiento < CURRENT_DATE))), (0)::numeric) AS total_vencido,
    GREATEST(max(f.created_at), ( SELECT max(p.created_at) AS max
           FROM (public.pagos p
             JOIN public.facturas fp ON ((p.factura_id = fp.id)))
          WHERE (fp.cliente_id = c.id)), ( SELECT max(cb.created_at) AS max
           FROM (public.cobros cb
             JOIN public.facturas fi ON ((cb.factura_id = fi.id)))
          WHERE (fi.cliente_id = c.id))) AS ultima_actividad
   FROM (public.clientes c
     LEFT JOIN public.facturas f ON (((f.cliente_id = c.id) AND (f.estado <> 'anulada'::text))))
  GROUP BY c.id, c.org_id, c.nombre, c.nombre_fantasia, c.cuit, c.estado, c.email, c.telefono, c.saldo_a_favor, c.saldo_a_favor_ivr
UNION ALL
 SELECT oc.id AS cliente_id,
    oc.org_id,
    COALESCE(((p.nombre || ' '::text) || COALESCE(p.apellido, ''::text)), p.nombre) AS nombre,
    NULL::text AS nombre_fantasia,
        CASE
            WHEN (p.documento_tipo = ANY (ARRAY['CUIT'::text, 'CUIL'::text])) THEN p.documento_nro
            ELSE NULL::text
        END AS cuit,
        CASE
            WHEN oc.activo THEN 'Activo'::text
            ELSE 'Inactivo'::text
        END AS estado,
    p.email,
    p.telefono,
    COALESCE(sum(
        CASE
            WHEN (f.tipo_factura <> 'IVR'::text) THEN f.total
            ELSE (0)::numeric
        END), (0)::numeric) AS total_facturado_legal,
    count(
        CASE
            WHEN (f.tipo_factura <> 'IVR'::text) THEN f.id
            ELSE NULL::uuid
        END) AS cantidad_facturas_legal,
    COALESCE(sum(
        CASE
            WHEN (f.tipo_factura = 'IVR'::text) THEN f.total
            ELSE (0)::numeric
        END), (0)::numeric) AS total_remitido_ivr,
    count(
        CASE
            WHEN (f.tipo_factura = 'IVR'::text) THEN f.id
            ELSE NULL::uuid
        END) AS cantidad_ivr,
    COALESCE(( SELECT sum(pg.monto) AS sum
           FROM (public.pagos pg
             JOIN public.facturas fp ON ((pg.factura_id = fp.id)))
          WHERE ((fp.cliente_id = oc.id) AND (fp.tipo_factura <> 'IVR'::text))), (0)::numeric) AS total_pagado_legal,
    COALESCE(( SELECT sum(cb.monto) AS sum
           FROM (public.cobros cb
             JOIN public.facturas fi ON ((cb.factura_id = fi.id)))
          WHERE ((fi.cliente_id = oc.id) AND (fi.tipo_factura = 'IVR'::text))), (0)::numeric) AS total_cobrado_ivr,
    COALESCE(( SELECT sum(nc.monto) AS sum
           FROM (public.notas_credito nc
             JOIN public.facturas fn ON ((nc.factura_id = fn.id)))
          WHERE ((fn.cliente_id = oc.id) AND (fn.tipo_factura <> 'IVR'::text))), (0)::numeric) AS total_notas_credito,
    ((COALESCE(sum(
        CASE
            WHEN (f.tipo_factura <> 'IVR'::text) THEN f.total
            ELSE (0)::numeric
        END), (0)::numeric) - COALESCE(( SELECT sum(pg.monto) AS sum
           FROM (public.pagos pg
             JOIN public.facturas fp ON ((pg.factura_id = fp.id)))
          WHERE ((fp.cliente_id = oc.id) AND (fp.tipo_factura <> 'IVR'::text))), (0)::numeric)) - COALESCE(( SELECT sum(nc.monto) AS sum
           FROM (public.notas_credito nc
             JOIN public.facturas fn ON ((nc.factura_id = fn.id)))
          WHERE ((fn.cliente_id = oc.id) AND (fn.tipo_factura <> 'IVR'::text))), (0)::numeric)) AS saldo_legal,
    (COALESCE(sum(
        CASE
            WHEN (f.tipo_factura = 'IVR'::text) THEN f.total
            ELSE (0)::numeric
        END), (0)::numeric) - COALESCE(( SELECT sum(cb.monto) AS sum
           FROM (public.cobros cb
             JOIN public.facturas fi ON ((cb.factura_id = fi.id)))
          WHERE ((fi.cliente_id = oc.id) AND (fi.tipo_factura = 'IVR'::text))), (0)::numeric)) AS saldo_ivr,
    COALESCE(oc.saldo_a_favor, (0)::numeric) AS saldo_a_favor_legal,
    COALESCE(oc.saldo_a_favor_ivr, (0)::numeric) AS saldo_a_favor_ivr,
    COALESCE(( SELECT sum((f2.total - COALESCE(( SELECT sum(p2.monto) AS sum
                   FROM public.pagos p2
                  WHERE (p2.factura_id = f2.id)), (0)::numeric))) AS sum
           FROM public.facturas f2
          WHERE ((f2.cliente_id = oc.id) AND (f2.tipo_factura <> 'IVR'::text) AND (f2.estado <> ALL (ARRAY['pagada'::text, 'anulada'::text])) AND (f2.fecha_vencimiento < CURRENT_DATE))), (0)::numeric) AS total_vencido,
    GREATEST(max(f.created_at), ( SELECT max(pg.created_at) AS max
           FROM (public.pagos pg
             JOIN public.facturas fp ON ((pg.factura_id = fp.id)))
          WHERE (fp.cliente_id = oc.id)), ( SELECT max(cb.created_at) AS max
           FROM (public.cobros cb
             JOIN public.facturas fi ON ((cb.factura_id = fi.id)))
          WHERE (fi.cliente_id = oc.id))) AS ultima_actividad
   FROM ((public.org_contacts oc
     JOIN public.personas p ON ((p.id = oc.persona_id)))
     LEFT JOIN public.facturas f ON (((f.cliente_id = oc.id) AND (f.estado <> 'anulada'::text))))
  WHERE (oc.tipo = ANY (ARRAY['cliente'::text, 'ambos'::text]))
  GROUP BY oc.id, oc.org_id, p.nombre, p.apellido, p.documento_tipo, p.documento_nro, p.email, p.telefono, oc.activo, oc.saldo_a_favor, oc.saldo_a_favor_ivr;


--
-- Name: vista_cuentas_corrientes_ivr; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vista_cuentas_corrientes_ivr AS
 SELECT c.id AS cliente_id,
    c.org_id,
    c.nombre,
    c.nombre_fantasia,
    c.identificador_unico,
    c.identificador_legacy,
    c.cuit,
    c.estado,
    COALESCE(ivr_totals.total_remitido, (0)::numeric) AS total_remitido,
    COALESCE(ivr_totals.cantidad_ivr, (0)::bigint) AS cantidad_ivr,
    COALESCE(cobro_totals.total_cobrado, (0)::numeric) AS total_cobrado,
    COALESCE(cobro_totals.cantidad_cobros, (0)::bigint) AS cantidad_cobros,
    (((COALESCE(ivr_totals.total_remitido, (0)::numeric) - COALESCE(cobro_totals.total_cobrado, (0)::numeric)) - COALESCE(c.saldo_a_favor_ivr, (0)::numeric)) - COALESCE(nc_totals.total_nc, (0)::numeric)) AS saldo_actual,
    COALESCE(ivr_totals.total_pendiente, (0)::numeric) AS total_pendiente,
    COALESCE(ivr_totals.cantidad_pendientes, (0)::bigint) AS cantidad_pendientes,
    COALESCE(ivr_totals.total_cobrado_full, (0)::numeric) AS total_cobrado_full,
    COALESCE(ivr_totals.cantidad_cobrados, (0)::bigint) AS cantidad_cobrados,
    GREATEST(COALESCE(ivr_totals.ultima_emision, '1900-01-01'::date), COALESCE(cobro_totals.ultimo_cobro, '1900-01-01'::date)) AS ultima_actividad,
    COALESCE(c.saldo_a_favor_ivr, (0)::numeric) AS saldo_a_favor_ivr,
    COALESCE(nc_totals.total_nc, (0)::numeric) AS total_notas_credito,
    COALESCE(nc_totals.cantidad_nc, (0)::bigint) AS cantidad_notas_credito
   FROM (((public.clientes c
     LEFT JOIN ( SELECT f.cliente_id,
            sum(f.total) AS total_remitido,
            count(f.id) AS cantidad_ivr,
            sum(
                CASE
                    WHEN (f.estado = ANY (ARRAY['pendiente'::text, 'parcial'::text])) THEN f.total
                    ELSE (0)::numeric
                END) AS total_pendiente,
            count(
                CASE
                    WHEN (f.estado = ANY (ARRAY['pendiente'::text, 'parcial'::text])) THEN 1
                    ELSE NULL::integer
                END) AS cantidad_pendientes,
            sum(
                CASE
                    WHEN (f.estado = 'pagada'::text) THEN f.total
                    ELSE (0)::numeric
                END) AS total_cobrado_full,
            count(
                CASE
                    WHEN (f.estado = 'pagada'::text) THEN 1
                    ELSE NULL::integer
                END) AS cantidad_cobrados,
            max(f.fecha_emision) AS ultima_emision
           FROM public.facturas f
          WHERE ((f.tipo_factura = 'IVR'::text) AND (f.estado <> 'anulada'::text))
          GROUP BY f.cliente_id) ivr_totals ON ((ivr_totals.cliente_id = c.id)))
     LEFT JOIN ( SELECT f.cliente_id,
            sum(ca.monto_aplicado) AS total_cobrado,
            count(DISTINCT co.id) AS cantidad_cobros,
            max(co.fecha_pago) AS ultimo_cobro
           FROM ((public.cobros_aplicaciones ca
             JOIN public.cobros co ON ((ca.cobro_id = co.id)))
             JOIN public.facturas f ON (((ca.factura_id = f.id) AND (f.tipo_factura = 'IVR'::text))))
          GROUP BY f.cliente_id) cobro_totals ON ((cobro_totals.cliente_id = c.id)))
     LEFT JOIN ( SELECT COALESCE(f.cliente_id, nc.cliente_id) AS cliente_id,
            sum(nc.monto) AS total_nc,
            count(nc.id) AS cantidad_nc
           FROM (public.notas_credito nc
             LEFT JOIN public.facturas f ON (((nc.factura_id = f.id) AND (f.tipo_factura = 'IVR'::text))))
          WHERE ((nc.factura_id IS NOT NULL) OR (nc.cliente_id IS NOT NULL))
          GROUP BY COALESCE(f.cliente_id, nc.cliente_id)) nc_totals ON ((nc_totals.cliente_id = c.id)))
  WHERE ((ivr_totals.cantidad_ivr > 0) OR (c.saldo_a_favor_ivr > (0)::numeric));


--
-- Name: vista_equipos_insumos_completa; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vista_equipos_insumos_completa AS
 SELECT e.id AS equipo_id,
    e.marca AS equipo_marca,
    e.modelo AS equipo_modelo,
    e.categoria AS equipo_categoria,
    p.id AS producto_id,
    p.codigo AS producto_codigo,
    p.nombre AS producto_nombre,
    p.nombre_comercial,
    p.categoria AS producto_categoria,
    p.fabricante,
    p.precio_venta,
    p.stock_actual,
    ei.es_compatible,
    ei.es_recomendado,
    ei.consumo_aproximado,
    ei.unidad_consumo,
    ei.notas
   FROM ((public.equipos e
     JOIN public.equipos_insumos ei ON ((e.id = ei.equipo_id)))
     JOIN public.productos p ON ((ei.producto_id = p.id)))
  ORDER BY e.marca, e.modelo, ei.es_recomendado DESC, p.nombre_comercial, p.nombre;


--
-- Name: vista_movimientos_cuenta_corriente; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vista_movimientos_cuenta_corriente AS
 SELECT f.cliente_id,
    f.fecha_emision AS fecha,
    'factura_legal'::text AS tipo_movimiento,
    concat('Factura ', f.tipo_factura, ' ', COALESCE(f.nro_factura, ((f.id)::text)::character varying)) AS descripcion,
    f.total AS debito,
    0 AS credito,
    f.id AS documento_id,
    'legal'::text AS cuenta
   FROM public.facturas f
  WHERE ((f.tipo_factura <> 'IVR'::text) AND (f.estado <> 'anulada'::text))
UNION ALL
 SELECT f.cliente_id,
    f.fecha_emision AS fecha,
    'factura_ivr'::text AS tipo_movimiento,
    concat('Remito IVR ', COALESCE(f.nro_factura, ((f.id)::text)::character varying)) AS descripcion,
    f.total AS debito,
    0 AS credito,
    f.id AS documento_id,
    'ivr'::text AS cuenta
   FROM public.facturas f
  WHERE ((f.tipo_factura = 'IVR'::text) AND (f.estado <> 'anulada'::text))
UNION ALL
 SELECT fp.cliente_id,
    p.fecha_pago AS fecha,
    'pago_legal'::text AS tipo_movimiento,
    concat('Pago ', p.metodo_pago, ' - Fact. ', COALESCE(fp.nro_factura, ((fp.id)::text)::character varying)) AS descripcion,
    0 AS debito,
    p.monto AS credito,
    p.id AS documento_id,
    'legal'::text AS cuenta
   FROM (public.pagos p
     JOIN public.facturas fp ON ((p.factura_id = fp.id)))
  WHERE (fp.tipo_factura <> 'IVR'::text)
UNION ALL
 SELECT fi.cliente_id,
    cb.fecha_pago AS fecha,
    'cobro_ivr'::text AS tipo_movimiento,
    concat('Cobro ', cb.metodo_pago, ' - IVR ', COALESCE(fi.nro_factura, ((fi.id)::text)::character varying)) AS descripcion,
    0 AS debito,
    cb.monto AS credito,
    cb.id AS documento_id,
    'ivr'::text AS cuenta
   FROM (public.cobros cb
     JOIN public.facturas fi ON ((cb.factura_id = fi.id)))
  WHERE (fi.tipo_factura = 'IVR'::text)
UNION ALL
 SELECT fn.cliente_id,
    (nc.created_at)::date AS fecha,
    'nota_credito'::text AS tipo_movimiento,
    concat('NC: ', nc.motivo) AS descripcion,
    0 AS debito,
    nc.monto AS credito,
    nc.id AS documento_id,
    'legal'::text AS cuenta
   FROM (public.notas_credito nc
     JOIN public.facturas fn ON ((nc.factura_id = fn.id)))
  WHERE (fn.tipo_factura <> 'IVR'::text)
  ORDER BY 2 DESC;


--
-- Name: VIEW vista_movimientos_cuenta_corriente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.vista_movimientos_cuenta_corriente IS 'Movimientos detallados de cuenta corriente con columna cuenta para filtrar legal/ivr';


--
-- Name: vista_movimientos_ivr; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vista_movimientos_ivr AS
 WITH movimientos AS (
         SELECT f.cliente_id,
            f.id AS movimiento_id,
            'ivr'::text AS tipo_movimiento,
            f.fecha_emision AS fecha,
            concat('IVR-', COALESCE(f.nro_factura, ((f.id)::text)::character varying)) AS descripcion,
            f.total AS debito,
            (0)::numeric AS credito,
            f.estado,
            f.created_at
           FROM public.facturas f
          WHERE (f.tipo_factura = 'IVR'::text)
        UNION ALL
         SELECT f.cliente_id,
            co.id AS movimiento_id,
            'cobro'::text AS tipo_movimiento,
            co.fecha_pago AS fecha,
            'Cobro'::text AS descripcion,
            (0)::numeric AS debito,
            co.monto AS credito,
            'aplicado'::text AS estado,
            co.created_at
           FROM (public.cobros co
             JOIN public.facturas f ON (((f.id = co.factura_id) AND (f.tipo_factura = 'IVR'::text))))
        UNION ALL
         SELECT COALESCE(f.cliente_id, nc.cliente_id) AS cliente_id,
            nc.id AS movimiento_id,
            'nota_credito'::text AS tipo_movimiento,
            COALESCE(nc.fecha, (nc.created_at)::date) AS fecha,
            concat('NC-', COALESCE(nc.nro_nota, ((nc.id)::text)::character varying)) AS descripcion,
            (0)::numeric AS debito,
            nc.monto AS credito,
            'aplicada'::text AS estado,
            nc.created_at
           FROM (public.notas_credito nc
             LEFT JOIN public.facturas f ON (((nc.factura_id = f.id) AND (f.tipo_factura = 'IVR'::text))))
          WHERE ((nc.factura_id IS NOT NULL) OR (nc.cliente_id IS NOT NULL))
        )
 SELECT m.cliente_id,
    m.movimiento_id,
    m.tipo_movimiento,
    m.fecha,
    m.descripcion,
    m.debito,
    m.credito,
    m.estado,
    m.created_at,
    c.nombre AS cliente_nombre,
    c.nombre_fantasia AS cliente_nombre_fantasia,
    c.identificador_unico AS cliente_identificador,
    sum((m.debito - m.credito)) OVER (PARTITION BY m.cliente_id ORDER BY m.fecha, m.created_at ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS saldo_acumulado
   FROM (movimientos m
     JOIN public.clientes c ON ((c.id = m.cliente_id)));


--
-- Name: vista_preparacion_entregas; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vista_preparacion_entregas AS
SELECT
    NULL::uuid AS id,
    NULL::character varying(50) AS numero,
    NULL::uuid AS cliente_id,
    NULL::character varying(255) AS cliente_nombre,
    NULL::character varying(100) AS tipo_cliente,
    NULL::character varying(255) AS ubicacion,
    NULL::character varying(50) AS estado,
    NULL::timestamp with time zone AS fecha_creacion,
    NULL::date AS fecha_requerida,
    NULL::timestamp with time zone AS fecha_listo,
    NULL::timestamp with time zone AS fecha_despacho,
    NULL::uuid AS instalacion_id,
    NULL::uuid AS envio_id,
    NULL::uuid AS responsable_id,
    NULL::character varying(255) AS responsable_nombre,
    NULL::text AS notas,
    NULL::text AS notas_internas,
    NULL::timestamp with time zone AS created_at,
    NULL::timestamp with time zone AS updated_at,
    NULL::uuid AS created_by,
    NULL::uuid AS updated_by,
    NULL::text AS cliente_nombre_full,
    NULL::text[] AS cliente_email,
    NULL::text[] AS cliente_telefono,
    NULL::bigint AS total_items,
    NULL::bigint AS items_pendientes,
    NULL::bigint AS items_en_deposito,
    NULL::bigint AS items_probados,
    NULL::bigint AS items_listos;


--
-- Name: VIEW vista_preparacion_entregas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.vista_preparacion_entregas IS 'Vista con resumen de estado de items por orden';


--
-- Name: vitalidad_analisis; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vitalidad_analisis (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    persona_id uuid NOT NULL,
    fecha date NOT NULL,
    laboratorio text,
    profesional text,
    protocolo_nro text,
    solicitado_por text,
    pdf_url text,
    notas text,
    created_at timestamp with time zone DEFAULT now()
);


--
-- Name: vitalidad_analisis_resultados; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vitalidad_analisis_resultados (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    analisis_id uuid NOT NULL,
    nombre text NOT NULL,
    valor numeric,
    unidad text,
    valor_texto text,
    ref_min numeric,
