--
-- Name: vw_balance_general; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_balance_general AS
 SELECT pc.tipo,
    pc.codigo,
    pc.nombre,
    pc.nivel,
    (COALESCE(sum(ai.debe), (0)::numeric) - COALESCE(sum(ai.haber), (0)::numeric)) AS saldo_deudor,
    (COALESCE(sum(ai.haber), (0)::numeric) - COALESCE(sum(ai.debe), (0)::numeric)) AS saldo_acreedor,
        CASE
            WHEN ((pc.tipo)::text = ANY (ARRAY[('activo'::character varying)::text, ('gasto'::character varying)::text])) THEN (COALESCE(sum(ai.debe), (0)::numeric) - COALESCE(sum(ai.haber), (0)::numeric))
            ELSE (COALESCE(sum(ai.haber), (0)::numeric) - COALESCE(sum(ai.debe), (0)::numeric))
        END AS saldo_neto
   FROM ((public.plan_cuentas pc
     LEFT JOIN public.asientos_items ai ON ((pc.id = ai.cuenta_id)))
     LEFT JOIN public.asientos_contables ac ON (((ai.asiento_id = ac.id) AND ((ac.estado)::text = 'confirmado'::text))))
  WHERE (pc.activa = true)
  GROUP BY pc.tipo, pc.codigo, pc.nombre, pc.nivel
  ORDER BY pc.codigo;


--
-- Name: vw_estado_resultados; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_estado_resultados AS
 SELECT date_trunc('month'::text, (ac.fecha)::timestamp with time zone) AS periodo,
    pc.tipo,
    pc.subtipo,
    pc.codigo,
    pc.nombre,
        CASE
            WHEN ((pc.tipo)::text = 'ingreso'::text) THEN (COALESCE(sum(ai.haber), (0)::numeric) - COALESCE(sum(ai.debe), (0)::numeric))
            WHEN ((pc.tipo)::text = 'gasto'::text) THEN (COALESCE(sum(ai.debe), (0)::numeric) - COALESCE(sum(ai.haber), (0)::numeric))
            ELSE (0)::numeric
        END AS monto
   FROM ((public.plan_cuentas pc
     LEFT JOIN public.asientos_items ai ON ((pc.id = ai.cuenta_id)))
     LEFT JOIN public.asientos_contables ac ON (((ai.asiento_id = ac.id) AND ((ac.estado)::text = 'confirmado'::text))))
  WHERE (((pc.tipo)::text = ANY (ARRAY[('ingreso'::character varying)::text, ('gasto'::character varying)::text])) AND (pc.activa = true))
  GROUP BY (date_trunc('month'::text, (ac.fecha)::timestamp with time zone)), pc.tipo, pc.subtipo, pc.codigo, pc.nombre
  ORDER BY (date_trunc('month'::text, (ac.fecha)::timestamp with time zone)) DESC, pc.tipo, pc.codigo;


--
-- Name: vw_productos_stock_bajo; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_productos_stock_bajo AS
 SELECT id,
    codigo,
    nombre,
    stock_actual,
    stock_minimo,
    categoria
   FROM public.productos
  WHERE ((stock_actual <= stock_minimo) AND (stock_minimo > (0)::numeric));


