--
-- Name: personas_with_orgs _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.personas_with_orgs AS
 SELECT p.id,
    p.documento_tipo,
    p.documento_nro,
    p.nombre,
    p.email,
    p.telefono,
    p.fecha_nacimiento,
    p.created_at,
    p.updated_at,
    COALESCE(json_agg(json_build_object('org_id', o.id, 'org_slug', o.slug, 'org_nombre', o.nombre, 'rol', om.rol, 'permisos', om.permisos)) FILTER (WHERE (o.id IS NOT NULL)), '[]'::json) AS organizations
   FROM ((public.personas p
     LEFT JOIN public.org_members om ON ((om.persona_id = p.id)))
     LEFT JOIN public.organizations o ON ((o.id = om.org_id)))
  GROUP BY p.id;


--
-- Name: vista_preparacion_entregas _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.vista_preparacion_entregas AS
 SELECT pe.id,
    pe.numero,
    pe.cliente_id,
    pe.cliente_nombre,
    pe.tipo_cliente,
    pe.ubicacion,
    pe.estado,
    pe.fecha_creacion,
    pe.fecha_requerida,
    pe.fecha_listo,
    pe.fecha_despacho,
    pe.instalacion_id,
    pe.envio_id,
    pe.responsable_id,
    pe.responsable_nombre,
    pe.notas,
    pe.notas_internas,
    pe.created_at,
    pe.updated_at,
    pe.created_by,
    pe.updated_by,
    c.nombre AS cliente_nombre_full,
    c.email AS cliente_email,
    c.telefono AS cliente_telefono,
    count(pei.id) AS total_items,
    count(
        CASE
            WHEN ((pei.estado)::text = 'pendiente'::text) THEN 1
            ELSE NULL::integer
        END) AS items_pendientes,
    count(
        CASE
            WHEN ((pei.estado)::text = 'en_deposito'::text) THEN 1
            ELSE NULL::integer
        END) AS items_en_deposito,
    count(
        CASE
            WHEN ((pei.estado)::text = 'probado'::text) THEN 1
            ELSE NULL::integer
        END) AS items_probados,
    count(
        CASE
            WHEN ((pei.estado)::text = 'listo'::text) THEN 1
            ELSE NULL::integer
        END) AS items_listos
   FROM ((public.preparacion_entregas pe
     LEFT JOIN public.clientes c ON ((pe.cliente_id = c.id)))
     LEFT JOIN public.preparacion_entregas_items pei ON ((pe.id = pei.preparacion_id)))
  GROUP BY pe.id, c.id;


